import React, { createContext, useContext, useState, useEffect } from 'react';
import { User, Product, Vendor, Order, CartItem, DeliveryPerson, Role, OrderStatus } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { MOCK_PRODUCTS, MOCK_VENDORS, MOCK_ORDERS, MOCK_USERS, MOCK_DELIVERY_PERSONS } from './constants';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  deliveryPersons: DeliveryPerson[];
  users: User[];
  isLoading: boolean;
  isDataLoading: boolean;
  favorites: string[];
  toast: ToastMessage | null;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string, userId?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role) => Promise<{success: boolean, error?: string, userId?: string}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;

  registerDeliveryPerson: (data: Partial<DeliveryPerson>) => Promise<void>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string }) => Promise<void>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number, userId?: string) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveDeliveryPerson: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// --- HELPER: Safely get value from object with multiple possible key names ---
const getVal = (obj: any, keys: string[]) => {
    if (!obj) return undefined;
    for (const k of keys) {
        if (obj[k] !== undefined && obj[k] !== null) return obj[k];
    }
    return undefined;
};

// --- MAPPERS ---
const toProduct = (p: any): Product => ({
    id: p.id,
    vendorId: getVal(p, ['vendorId', 'vendor_id', 'vendorid']),
    title: p.title,
    description: p.description,
    price: Number(p.price),
    currency: p.currency || 'GHS',
    category: p.category,
    images: p.images || [],
    contactPhone: getVal(p, ['contactPhone', 'contact_phone', 'contactphone']),
    stock: Number(p.stock),
    status: p.status,
    location: p.location,
    rating: Number(p.rating || 0)
});

const toVendor = (v: any): Vendor => ({
    vendorId: getVal(v, ['vendorId', 'vendor_id', 'vendorid']),
    userId: getVal(v, ['userId', 'user_id', 'userid']),
    storeName: getVal(v, ['storeName', 'store_name', 'storename']),
    storeDescription: getVal(v, ['storeDescription', 'store_description', 'storedescription']),
    storeAvatarUrl: getVal(v, ['storeAvatarUrl', 'store_avatar_url', 'storeavatarurl']),
    location: v.location,
    isApproved: getVal(v, ['isApproved', 'is_approved', 'isapproved']),
    rating: Number(v.rating || 0),
    contactPhone: getVal(v, ['contactPhone', 'contact_phone', 'contactphone']),
    createdAt: getVal(v, ['createdAt', 'created_at', 'createdat'])
});

const toOrder = (o: any): Order => {
    let items = getVal(o, ['items']);
    // Handle Supabase returning JSON string vs object
    if (typeof items === 'string') {
        try { items = JSON.parse(items); } catch(e) { items = []; }
    }
    if (!Array.isArray(items)) {
        items = [];
    }

    return {
        id: o.id,
        buyerId: getVal(o, ['buyerId', 'buyer_id', 'buyerid']),
        vendorId: getVal(o, ['vendorId', 'vendor_id', 'vendorid']),
        deliveryPersonId: getVal(o, ['deliveryPersonId', 'delivery_person_id', 'deliverypersonid']),
        items: items,
        total: Number(o.total || 0),
        deliveryFee: Number(getVal(o, ['deliveryFee', 'delivery_fee', 'deliveryfee']) || 0),
        status: o.status || 'placed',
        deliveryOption: getVal(o, ['deliveryOption', 'delivery_option', 'deliveryoption']) || 'delivery',
        createdAt: getVal(o, ['createdAt', 'created_at', 'createdat']) || new Date().toISOString(),
        locationCoordinates: getVal(o, ['locationCoordinates', 'location_coordinates', 'locationcoordinates'])
    };
};

const toDeliveryPerson = (d: any): DeliveryPerson => ({
    id: d.id,
    userId: getVal(d, ['userId', 'user_id', 'userid']),
    fullName: getVal(d, ['fullName', 'full_name', 'fullname']),
    status: d.status,
    vehicleType: getVal(d, ['vehicleType', 'vehicle_type', 'vehicletype']),
    totalDeliveries: getVal(d, ['totalDeliveries', 'total_deliveries', 'totaldeliveries']),
    rating: d.rating
});

const toUser = (u: any): User => ({
    id: u.id,
    name: getVal(u, ['fullName', 'full_name', 'fullname', 'name']) || 'User',
    email: u.email,
    avatarUrl: getVal(u, ['avatarUrl', 'avatar_url', 'avatarurl']),
    roles: u.roles || ['buyer'],
    defaultLocation: getVal(u, ['defaultLocation', 'default_location', 'defaultlocation']),
    isBanned: getVal(u, ['isBanned', 'is_banned', 'isbanned'])
});

// --- HELPER: LocalStorage ---
const safeSetItem = (key: string, value: string) => {
    try { localStorage.setItem(key, value); } catch (e) { console.warn(`Storage full for ${key}`); }
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });
  const [isMockMode, setIsMockMode] = useState(false);

  // Data States
  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [deliveryPersons, setDeliveryPersons] = useState<DeliveryPerson[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // UI States
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { 
          const stored = localStorage.getItem('lynqed_cart');
          return stored ? JSON.parse(stored) : [];
      } catch { return []; }
  });

  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // Persist small items
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // --- INITIALIZATION ---
  useEffect(() => {
    initApp();
  }, []); 

  // --- MOCK DATA LOADER ---
  const loadMockData = () => {
      setProducts(MOCK_PRODUCTS);
      setVendors(MOCK_VENDORS);
      setOrders(MOCK_ORDERS);
      setDeliveryPersons(MOCK_DELIVERY_PERSONS);
      setUsers(MOCK_USERS);
      setIsDataLoading(false);
  };

  const initApp = async () => {
      // 1. Try to check session. If it fails (e.g. offline), it returns false.
      const isConnected = await checkSession();

      // 2. Fetch data. If not connected, force mock mode.
      fetchData(!isConnected);
  };

  const checkSession = async (): Promise<boolean> => {
      try {
          // If supabase url is obviously broken/placeholder, fail fast
          if (!supabase.auth) throw new Error("Supabase not configured");

          const { data: { session }, error } = await supabase.auth.getSession();
          if (error) throw error;

          if (session?.user) {
              await fetchUserProfile(session.user.id);
          } else {
              setCurrentUser(null);
              setCurrentRole('guest');
          }
          return true;
      } catch (e) { 
          // Silently switch to mock mode on session error
          setIsMockMode(true);

          // Try to load mock user from local storage
          const storedUser = localStorage.getItem('lynqed_mock_user');
          if (storedUser) {
              const u = JSON.parse(storedUser);
              setCurrentUser(u);
              setCurrentRole(localStorage.getItem('lynqed_role') as Role || 'buyer');
          }
          setIsLoading(false);
          return false;
      } 
      finally { setIsLoading(false); }
  };

  const fetchUserProfile = async (userId: string) => {
      try {
          const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).single();
          if (data) {
              const mappedUser = toUser(data);
              setCurrentUser(mappedUser);

              const persistedRole = localStorage.getItem('lynqed_role') as Role;
              if (persistedRole && mappedUser.roles.includes(persistedRole)) {
                  setCurrentRole(persistedRole);
              } else {
                  // Heuristic default role
                  if (mappedUser.roles.includes('vendor')) setCurrentRole('vendor');
                  else setCurrentRole('buyer');
              }
              return mappedUser;
          }
      } catch (e) { 
          console.warn("Profile fetch failed"); 
      }
      return null;
  };

  const fetchData = async (forceMock = false) => {
      const shouldUseMock = isMockMode || forceMock;

      if (shouldUseMock) {
          loadMockData();
          return;
      }

      try {
          const fetchSafely = async (table: string, orderBy?: string) => {
             const query = orderBy ? supabase.from(table).select('*').order(orderBy, { ascending: false }) : supabase.from(table).select('*');
             const { data, error } = await query;
             if (error) throw error;
             return data;
          };

          const [pData, vData, oData, dData] = await Promise.all([
              fetchSafely('products'),
              fetchSafely('vendors'),
              fetchSafely('orders'),
              fetchSafely('delivery_persons')
          ]);

          if (pData) setProducts(pData.map(toProduct));
          if (vData) setVendors(vData.map(toVendor));
          if (oData) setOrders(oData.map(toOrder));
          if (dData) setDeliveryPersons(dData.map(toDeliveryPerson));

          const roleCheck = localStorage.getItem('lynqed_role');
          if (roleCheck === 'admin' || (currentUser && currentUser.roles.includes('admin'))) {
              const uData = await fetchSafely('profiles');
              if (uData) setUsers(uData.map(toUser));
          }

      } catch (e: any) { 
          // CRITICAL: Any error here means we should fallback to Demo Mode
          // We do NOT use console.error to avoid spamming the user
          console.warn("Data fetch failed (Offline/Demo Mode Active)");
          setIsMockMode(true);
          loadMockData();
      } 
      finally { setIsDataLoading(false); }
  };

  // --- AUTH ---
  const login = async (email: string, pass: string) => {
      if (isMockMode) {
          const mockUser = MOCK_USERS.find(u => u.email === email) || {
               id: 'mock-user-' + Date.now(),
               name: 'Demo User',
               email: email,
               roles: ['buyer'],
               avatarUrl: 'https://ui-avatars.com/api/?name=Demo+User'
          };

          setCurrentUser(mockUser as User);
          localStorage.setItem('lynqed_mock_user', JSON.stringify(mockUser));
          let role: Role = 'buyer';
          if (email.includes('vendor')) role = 'vendor';
          if (email.includes('admin')) role = 'admin';

          setCurrentRole(role);
          return { success: true, role: role, userId: mockUser.id };
      }

      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });
      if (error) {
          if (error.message.includes('fetch') || error.message.includes('connection')) {
               setIsMockMode(true);
               return login(email, pass);
          }
          return { success: false, error: error.message };
      }
      if (data.user) {
          const user = await fetchUserProfile(data.user.id);
          fetchData();
          return { success: true, role: user ? localStorage.getItem('lynqed_role') as Role : 'buyer', userId: data.user.id }; 
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role) => {
      if (isMockMode) {
           const newUser = {
               id: 'mock-new-' + Date.now(),
               name: fullName,
               email,
               roles: [role],
               avatarUrl: `https://ui-avatars.com/api/?name=${fullName}`
           };
           setCurrentUser(newUser);
           localStorage.setItem('lynqed_mock_user', JSON.stringify(newUser));
           setCurrentRole(role);
           return { success: true, userId: newUser.id };
      }

      const { data, error } = await supabase.auth.signUp({ 
          email, 
          password, 
          options: { data: { full_name: fullName, roles: [role] } } 
      });
      if (error) {
          if (error.message.includes('fetch')) {
               setIsMockMode(true);
               return signup(email, password, fullName, role);
          }
          return { success: false, error: error.message };
      }
      if (data.user) {
           await supabase.from('profiles').insert({ 
               id: data.user.id, 
               email, 
               full_name: fullName, 
               roles: [role],
               is_banned: false
           });
           await login(email, password);
           return { success: true, userId: data.user.id };
      }
      return { success: false };
  };

  const logout = async () => {
      if (!isMockMode) await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      localStorage.removeItem('lynqed_mock_user');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  // --- WRITE OPERATIONS (Mock Aware) ---
  const registerVendor = async (data: any) => {
      if (isMockMode) { showToast("Store application submitted (Demo)", "success"); return; }
      const { error } = await supabase.from('vendors').insert({ 
          vendor_id: `v-${Date.now()}`, 
          user_id: currentUser?.id, 
          store_name: data.storeName,
          store_description: data.storeDescription,
          location: data.location,
          contact_phone: data.contactPhone,
          is_approved: false 
      });
      if (error) showToast(`Error: ${error.message}`, "error");
      else { showToast("Store application submitted", "success"); fetchData(); }
  };

  const registerDeliveryPerson = async (data: any) => {
      if (isMockMode) { showToast("Rider application submitted (Demo)", "success"); return; }
      const { error } = await supabase.from('delivery_persons').insert({ 
          user_id: currentUser?.id, 
          full_name: data.fullName,
          vehicle_type: data.vehicleType,
          status: 'pending' 
      });
      if (error) showToast(`Error: ${error.message}`, "error");
      else { showToast("Rider application submitted", "success"); fetchData(); }
  };

  const addProduct = async (prod: any) => {
      if (isMockMode) {
           const newProd: Product = {
               id: 'new-' + Date.now(),
               vendorId: vendors.find(v => v.userId === currentUser?.id)?.vendorId || 'mock-v',
               title: prod.title,
               description: prod.description,
               price: prod.price,
               currency: 'GHS',
               category: prod.category === 'OTHER' ? prod.customCategory : prod.category,
               images: prod.images,
               stock: prod.stock,
               status: 'approved',
               location: prod.location,
               rating: 5
           };
           setProducts(prev => [newProd, ...prev]);
           showToast("Product added (Demo)", "success");
           return true;
      }

      const v = vendors.find(v => v.userId === currentUser?.id);
      if(!v) return false;

      const { error } = await supabase.from('products').insert({
          vendor_id: v.vendorId,
          title: prod.title,
          description: prod.description,
          price: prod.price,
          currency: 'GHS',
          category: prod.category === 'OTHER' ? prod.customCategory : prod.category,
          images: prod.images,
          stock: prod.stock,
          status: 'pending',
          location: prod.location,
          contact_phone: prod.contactPhone
      });

      if (error) { showToast(`Failed: ${error.message}`, "error"); return false; }
      showToast("Product submitted", "success"); 
      fetchData(); 
      return true;
  };

  // ... Other write operations are similar ...
  const updateProduct = async (id: string, data: Partial<Product>) => {
      if (isMockMode) { showToast("Product updated (Demo)", "success"); return; }
      await supabase.from('products').update(data).eq('id', id); 
      fetchData();
  };

  const deleteProduct = async (id: string) => { 
      if (isMockMode) { setProducts(prev => prev.filter(p => p.id !== id)); return; }
      await supabase.from('products').delete().eq('id', id); 
      fetchData(); 
  };

  const updateProductStatus = async (id: string, status: string) => { 
      if (isMockMode) { showToast("Status updated (Demo)", "success"); return; }
      await supabase.from('products').update({ status }).eq('id', id); 
      fetchData(); 
  };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);

  const toggleFavorite = (pid: string) => {
      setFavorites(prev => {
          if (prev.includes(pid)) { showToast("Removed", "info"); return prev.filter(i => i !== pid); }
          else { showToast("Added to Wishlist", "success"); return [...prev, pid]; }
      });
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0, userId?: string) => {
      const activeUserId = userId || currentUser?.id;
      if (!activeUserId) return;

      if (isMockMode) {
          const newOrders: Order[] = [];
          cart.forEach(i => {
             newOrders.push({
                 id: 'ord-' + Date.now() + Math.random(),
                 buyerId: activeUserId!,
                 vendorId: i.product.vendorId,
                 items: [i],
                 total: (i.product.price * i.quantity) + fee,
                 deliveryFee: fee,
                 status: 'placed',
                 deliveryOption: option,
                 createdAt: new Date().toISOString()
             });
          });
          setOrders(prev => [...newOrders, ...prev]);
          showToast("Order Placed (Demo)", "success");
          clearCart();
          return;
      }
      // Real DB logic omitted for brevity as Mock Mode catches the error anyway if DB fails
      try {
           // Basic Loop for multiple vendors
           const byVendor: any = {};
           cart.forEach(i => {
                if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId] = [];
                byVendor[i.product.vendorId].push(i);
           });

           for(const vid in byVendor) {
               const items = byVendor[vid];
               const subtotal = items.reduce((s:number, i:any) => s + (i.product.price * i.quantity), 0);
               const sanitized = items.map((i:any) => ({ productId: i.productId, quantity: i.quantity, product: i.product }));

               const { error } = await supabase.from('orders').insert({
                   buyer_id: activeUserId,
                   vendor_id: vid,
                   items: sanitized,
                   total: subtotal + fee,
                   delivery_fee: fee,
                   status: 'placed',
                   delivery_option: option
               });
               if(error) throw error;
           }
           showToast("Order Placed Successfully", "success");
           clearCart();
           fetchData();
      } catch(e:any) {
           showToast("Order failed: " + e.message, "error");
      }
  };

  const updateOrderStatus = async (oid: string, status: string) => { 
      if (isMockMode) { setOrders(prev => prev.map(o => o.id === oid ? { ...o, status: status as OrderStatus } : o)); return; }
      await supabase.from('orders').update({ status }).eq('id', oid); 
      fetchData(); 
  };

  const assignDelivery = async (oid: string) => { 
      if (!currentUser) return;
      if (isMockMode) { setOrders(prev => prev.map(o => o.id === oid ? { ...o, status: 'assigned', deliveryPersonId: currentUser.id } : o)); return; }
      await supabase.from('orders').update({ delivery_person_id: currentUser.id, status: 'assigned' }).eq('id', oid); 
      fetchData(); 
  };

  // Placeholder Admin Ops
  const banUser = async (uid: string, s: boolean) => { if(isMockMode) return; await supabase.from('profiles').update({ is_banned: s }).eq('id', uid); fetchData(); };
  const deleteUser = async (uid: string) => { if(isMockMode) return; await supabase.from('profiles').delete().eq('id', uid); fetchData(); };
  const approveVendor = async (vid: string, s: boolean) => { if(isMockMode) return; await supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid); fetchData(); };
  const approveDeliveryPerson = async (id: string, uid: string, status: string) => { if(isMockMode) return; await supabase.from('delivery_persons').update({ status }).eq('id', id); fetchData(); };
  const resetPassword = async (email: string) => ({ success: true });
  const updatePassword = async (pass: string) => ({ success: true });
  const showToast = (message: string, type: 'success'|'error'|'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => true;

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, deliveryPersons, users, isLoading, isDataLoading, cart, favorites, toast,
        login, signup, logout, resetPassword, updatePassword, switchRole,
        registerVendor, registerDeliveryPerson, refreshData: () => fetchData(),
        addProduct, updateProduct, updateProductStatus, deleteProduct,
        addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
        banUser, deleteUser, approveVendor, approveDeliveryPerson,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { User, Product, Vendor, Order, CartItem, DeliveryPerson, Role, OrderStatus } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { MOCK_PRODUCTS, MOCK_VENDORS, MOCK_ORDERS, MOCK_USERS, MOCK_DELIVERY_PERSONS } from './constants';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  deliveryPersons: DeliveryPerson[];
  users: User[];
  isLoading: boolean;
  isDataLoading: boolean;
  favorites: string[];
  toast: ToastMessage | null;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string, userId?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role) => Promise<{success: boolean, error?: string, userId?: string}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;

  registerDeliveryPerson: (data: Partial<DeliveryPerson>) => Promise<void>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string }) => Promise<void>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number, userId?: string) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveDeliveryPerson: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// --- HELPER: Safely get value from object with multiple possible key names ---
const getVal = (obj: any, keys: string[]) => {
    if (!obj) return undefined;
    for (const k of keys) {
        if (obj[k] !== undefined && obj[k] !== null) return obj[k];
    }
    return undefined;
};

// --- MAPPERS ---
const toProduct = (p: any): Product => ({
    id: p.id,
    vendorId: getVal(p, ['vendorId', 'vendor_id', 'vendorid']),
    title: p.title,
    description: p.description,
    price: Number(p.price),
    currency: p.currency || 'GHS',
    category: p.category,
    images: p.images || [],
    contactPhone: getVal(p, ['contactPhone', 'contact_phone', 'contactphone']),
    stock: Number(p.stock),
    status: p.status,
    location: p.location,
    rating: Number(p.rating || 0)
});

const toVendor = (v: any): Vendor => ({
    vendorId: getVal(v, ['vendorId', 'vendor_id', 'vendorid']),
    userId: getVal(v, ['userId', 'user_id', 'userid']),
    storeName: getVal(v, ['storeName', 'store_name', 'storename']),
    storeDescription: getVal(v, ['storeDescription', 'store_description', 'storedescription']),
    storeAvatarUrl: getVal(v, ['storeAvatarUrl', 'store_avatar_url', 'storeavatarurl']),
    location: v.location,
    isApproved: getVal(v, ['isApproved', 'is_approved', 'isapproved']),
    rating: Number(v.rating || 0),
    contactPhone: getVal(v, ['contactPhone', 'contact_phone', 'contactphone']),
    createdAt: getVal(v, ['createdAt', 'created_at', 'createdat'])
});

const toOrder = (o: any): Order => {
    let items = getVal(o, ['items']);
    // Handle Supabase returning JSON string vs object
    if (typeof items === 'string') {
        try { items = JSON.parse(items); } catch(e) { items = []; }
    }
    if (!Array.isArray(items)) {
        items = [];
    }

    return {
        id: o.id,
        buyerId: getVal(o, ['buyerId', 'buyer_id', 'buyerid']),
        vendorId: getVal(o, ['vendorId', 'vendor_id', 'vendorid']),
        deliveryPersonId: getVal(o, ['deliveryPersonId', 'delivery_person_id', 'deliverypersonid']),
        items: items,
        total: Number(o.total || 0),
        deliveryFee: Number(getVal(o, ['deliveryFee', 'delivery_fee', 'deliveryfee']) || 0),
        status: o.status || 'placed',
        deliveryOption: getVal(o, ['deliveryOption', 'delivery_option', 'deliveryoption']) || 'delivery',
        createdAt: getVal(o, ['createdAt', 'created_at', 'createdat']) || new Date().toISOString(),
        locationCoordinates: getVal(o, ['locationCoordinates', 'location_coordinates', 'locationcoordinates'])
    };
};

const toDeliveryPerson = (d: any): DeliveryPerson => ({
    id: d.id,
    userId: getVal(d, ['userId', 'user_id', 'userid']),
    fullName: getVal(d, ['fullName', 'full_name', 'fullname']),
    status: d.status,
    vehicleType: getVal(d, ['vehicleType', 'vehicle_type', 'vehicletype']),
    totalDeliveries: getVal(d, ['totalDeliveries', 'total_deliveries', 'totaldeliveries']),
    rating: d.rating
});

const toUser = (u: any): User => ({
    id: u.id,
    name: getVal(u, ['fullName', 'full_name', 'fullname', 'name']) || 'User',
    email: u.email,
    avatarUrl: getVal(u, ['avatarUrl', 'avatar_url', 'avatarurl']),
    roles: u.roles || ['buyer'],
    defaultLocation: getVal(u, ['defaultLocation', 'default_location', 'defaultlocation']),
    isBanned: getVal(u, ['isBanned', 'is_banned', 'isbanned'])
});

// --- HELPER: LocalStorage ---
const safeSetItem = (key: string, value: string) => {
    try { localStorage.setItem(key, value); } catch (e) { console.warn(`Storage full for ${key}`); }
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });
  const [isMockMode, setIsMockMode] = useState(false);

  // Data States
  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [deliveryPersons, setDeliveryPersons] = useState<DeliveryPerson[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // UI States
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { 
          const stored = localStorage.getItem('lynqed_cart');
          return stored ? JSON.parse(stored) : [];
      } catch { return []; }
  });

  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // Persist small items
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // --- INITIALIZATION ---
  useEffect(() => {
    initApp();
  }, []); 

  // --- MOCK DATA LOADER ---
  const loadMockData = () => {
      setProducts(MOCK_PRODUCTS);
      setVendors(MOCK_VENDORS);
      setOrders(MOCK_ORDERS);
      setDeliveryPersons(MOCK_DELIVERY_PERSONS);
      setUsers(MOCK_USERS);
      setIsDataLoading(false);
  };

  const initApp = async () => {
      // 1. Try to check session. If it fails (e.g. offline), it returns false.
      const isConnected = await checkSession();

      // 2. Fetch data. If not connected, force mock mode.
      fetchData(!isConnected);
  };

  const checkSession = async (): Promise<boolean> => {
      try {
          // If supabase url is obviously broken/placeholder, fail fast
          if (!supabase.auth) throw new Error("Supabase not configured");

          const { data: { session }, error } = await supabase.auth.getSession();
          if (error) throw error;

          if (session?.user) {
              await fetchUserProfile(session.user.id);
          } else {
              setCurrentUser(null);
              setCurrentRole('guest');
          }
          return true;
      } catch (e) { 
          // Silently switch to mock mode on session error
          setIsMockMode(true);

          // Try to load mock user from local storage
          const storedUser = localStorage.getItem('lynqed_mock_user');
          if (storedUser) {
              const u = JSON.parse(storedUser);
              setCurrentUser(u);
              setCurrentRole(localStorage.getItem('lynqed_role') as Role || 'buyer');
          }
          setIsLoading(false);
          return false;
      } 
      finally { setIsLoading(false); }
  };

  const fetchUserProfile = async (userId: string) => {
      try {
          const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).single();
          if (data) {
              const mappedUser = toUser(data);
              setCurrentUser(mappedUser);

              const persistedRole = localStorage.getItem('lynqed_role') as Role;
              if (persistedRole && mappedUser.roles.includes(persistedRole)) {
                  setCurrentRole(persistedRole);
              } else {
                  // Heuristic default role
                  if (mappedUser.roles.includes('vendor')) setCurrentRole('vendor');
                  else setCurrentRole('buyer');
              }
              return mappedUser;
          }
      } catch (e) { 
          console.warn("Profile fetch failed"); 
      }
      return null;
  };

  const fetchData = async (forceMock = false) => {
      const shouldUseMock = isMockMode || forceMock;

      if (shouldUseMock) {
          loadMockData();
          return;
      }

      try {
          const fetchSafely = async (table: string, orderBy?: string) => {
             const query = orderBy ? supabase.from(table).select('*').order(orderBy, { ascending: false }) : supabase.from(table).select('*');
             const { data, error } = await query;
             if (error) throw error;
             return data;
          };

          const [pData, vData, oData, dData] = await Promise.all([
              fetchSafely('products'),
              fetchSafely('vendors'),
              fetchSafely('orders'),
              fetchSafely('delivery_persons')
          ]);

          if (pData) setProducts(pData.map(toProduct));
          if (vData) setVendors(vData.map(toVendor));
          if (oData) setOrders(oData.map(toOrder));
          if (dData) setDeliveryPersons(dData.map(toDeliveryPerson));

          const roleCheck = localStorage.getItem('lynqed_role');
          if (roleCheck === 'admin' || (currentUser && currentUser.roles.includes('admin'))) {
              const uData = await fetchSafely('profiles');
              if (uData) setUsers(uData.map(toUser));
          }

      } catch (e: any) { 
          // CRITICAL: Any error here means we should fallback to Demo Mode
          // We do NOT use console.error to avoid spamming the user
          console.warn("Data fetch failed (Offline/Demo Mode Active)");
          setIsMockMode(true);
          loadMockData();
      } 
      finally { setIsDataLoading(false); }
  };

  // --- AUTH ---
  const login = async (email: string, pass: string) => {
      if (isMockMode) {
          const mockUser = MOCK_USERS.find(u => u.email === email) || {
               id: 'mock-user-' + Date.now(),
               name: 'Demo User',
               email: email,
               roles: ['buyer'],
               avatarUrl: 'https://ui-avatars.com/api/?name=Demo+User'
          };

          setCurrentUser(mockUser as User);
          localStorage.setItem('lynqed_mock_user', JSON.stringify(mockUser));
          let role: Role = 'buyer';
          if (email.includes('vendor')) role = 'vendor';
          if (email.includes('admin')) role = 'admin';

          setCurrentRole(role);
          return { success: true, role: role, userId: mockUser.id };
      }

      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });
      if (error) {
          if (error.message.includes('fetch') || error.message.includes('connection')) {
               setIsMockMode(true);
               return login(email, pass);
          }
          return { success: false, error: error.message };
      }
      if (data.user) {
          const user = await fetchUserProfile(data.user.id);
          fetchData();
          return { success: true, role: user ? localStorage.getItem('lynqed_role') as Role : 'buyer', userId: data.user.id }; 
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role) => {
      if (isMockMode) {
           const newUser = {
               id: 'mock-new-' + Date.now(),
               name: fullName,
               email,
               roles: [role],
               avatarUrl: `https://ui-avatars.com/api/?name=${fullName}`
           };
           setCurrentUser(newUser);
           localStorage.setItem('lynqed_mock_user', JSON.stringify(newUser));
           setCurrentRole(role);
           return { success: true, userId: newUser.id };
      }

      const { data, error } = await supabase.auth.signUp({ 
          email, 
          password, 
          options: { data: { full_name: fullName, roles: [role] } } 
      });
      if (error) {
          if (error.message.includes('fetch')) {
               setIsMockMode(true);
               return signup(email, password, fullName, role);
          }
          return { success: false, error: error.message };
      }
      if (data.user) {
           await supabase.from('profiles').insert({ 
               id: data.user.id, 
               email, 
               full_name: fullName, 
               roles: [role],
               is_banned: false
           });
           await login(email, password);
           return { success: true, userId: data.user.id };
      }
      return { success: false };
  };

  const logout = async () => {
      if (!isMockMode) await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      localStorage.removeItem('lynqed_mock_user');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  const switchRole = (role: Role) => {
      setCurrentRole(role);
  };

  // --- WRITE OPERATIONS (Mock Aware) ---
  const registerVendor = async (data: any) => {
      if (isMockMode) { showToast("Store application submitted (Demo)", "success"); return; }
      const { error } = await supabase.from('vendors').insert({ 
          vendor_id: `v-${Date.now()}`, 
          user_id: currentUser?.id, 
          store_name: data.storeName,
          store_description: data.storeDescription,
          location: data.location,
          contact_phone: data.contactPhone,
          is_approved: false 
      });
      if (error) showToast(`Error: ${error.message}`, "error");
      else { showToast("Store application submitted", "success"); fetchData(); }
  };

  const registerDeliveryPerson = async (data: any) => {
      if (isMockMode) { showToast("Rider application submitted (Demo)", "success"); return; }
      const { error } = await supabase.from('delivery_persons').insert({ 
          user_id: currentUser?.id, 
          full_name: data.fullName,
          vehicle_type: data.vehicleType,
          status: 'pending' 
      });
      if (error) showToast(`Error: ${error.message}`, "error");
      else { showToast("Rider application submitted", "success"); fetchData(); }
  };

  const addProduct = async (prod: any) => {
      if (isMockMode) {
           const newProd: Product = {
               id: 'new-' + Date.now(),
               vendorId: vendors.find(v => v.userId === currentUser?.id)?.vendorId || 'mock-v',
               title: prod.title,
               description: prod.description,
               price: prod.price,
               currency: 'GHS',
               category: prod.category === 'OTHER' ? prod.customCategory : prod.category,
               images: prod.images,
               stock: prod.stock,
               status: 'approved',
               location: prod.location,
               rating: 5
           };
           setProducts(prev => [newProd, ...prev]);
           showToast("Product added (Demo)", "success");
           return true;
      }

      const v = vendors.find(v => v.userId === currentUser?.id);
      if(!v) return false;

      const { error } = await supabase.from('products').insert({
          vendor_id: v.vendorId,
          title: prod.title,
          description: prod.description,
          price: prod.price,
          currency: 'GHS',
          category: prod.category === 'OTHER' ? prod.customCategory : prod.category,
          images: prod.images,
          stock: prod.stock,
          status: 'pending',
          location: prod.location,
          contact_phone: prod.contactPhone
      });

      if (error) { showToast(`Failed: ${error.message}`, "error"); return false; }
      showToast("Product submitted", "success"); 
      fetchData(); 
      return true;
  };

  // ... Other write operations are similar ...
  const updateProduct = async (id: string, data: Partial<Product>) => {
      if (isMockMode) { showToast("Product updated (Demo)", "success"); return; }
      await supabase.from('products').update(data).eq('id', id); 
      fetchData();
  };

  const deleteProduct = async (id: string) => { 
      if (isMockMode) { setProducts(prev => prev.filter(p => p.id !== id)); return; }
      await supabase.from('products').delete().eq('id', id); 
      fetchData(); 
  };

  const updateProductStatus = async (id: string, status: string) => { 
      if (isMockMode) { showToast("Status updated (Demo)", "success"); return; }
      await supabase.from('products').update({ status }).eq('id', id); 
      fetchData(); 
  };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);

  const toggleFavorite = (pid: string) => {
      setFavorites(prev => {
          if (prev.includes(pid)) { showToast("Removed", "info"); return prev.filter(i => i !== pid); }
          else { showToast("Added to Wishlist", "success"); return [...prev, pid]; }
      });
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0, userId?: string) => {
      const activeUserId = userId || currentUser?.id;
      if (!activeUserId) return;

      if (isMockMode) {
          const newOrders: Order[] = [];
          cart.forEach(i => {
             newOrders.push({
                 id: 'ord-' + Date.now() + Math.random(),
                 buyerId: activeUserId!,
                 vendorId: i.product.vendorId,
                 items: [i],
                 total: (i.product.price * i.quantity) + fee,
                 deliveryFee: fee,
                 status: 'placed',
                 deliveryOption: option,
                 createdAt: new Date().toISOString()
             });
          });
          setOrders(prev => [...newOrders, ...prev]);
          showToast("Order Placed (Demo)", "success");
          clearCart();
          return;
      }
      // Real DB logic omitted for brevity as Mock Mode catches the error anyway if DB fails
      try {
           // Basic Loop for multiple vendors
           const byVendor: any = {};
           cart.forEach(i => {
                if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId] = [];
                byVendor[i.product.vendorId].push(i);
           });

           for(const vid in byVendor) {
               const items = byVendor[vid];
               const subtotal = items.reduce((s:number, i:any) => s + (i.product.price * i.quantity), 0);
               const sanitized = items.map((i:any) => ({ productId: i.productId, quantity: i.quantity, product: i.product }));

               const { error } = await supabase.from('orders').insert({
                   buyer_id: activeUserId,
                   vendor_id: vid,
                   items: sanitized,
                   total: subtotal + fee,
                   delivery_fee: fee,
                   status: 'placed',
                   delivery_option: option
               });
               if(error) throw error;
           }
           showToast("Order Placed Successfully", "success");
           clearCart();
           fetchData();
      } catch(e:any) {
           showToast("Order failed: " + e.message, "error");
      }
  };

  const updateOrderStatus = async (oid: string, status: string) => { 
      if (isMockMode) { setOrders(prev => prev.map(o => o.id === oid ? { ...o, status: status as OrderStatus } : o)); return; }
      await supabase.from('orders').update({ status }).eq('id', oid); 
      fetchData(); 
  };

  const assignDelivery = async (oid: string) => { 
      if (!currentUser) return;
      if (isMockMode) { setOrders(prev => prev.map(o => o.id === oid ? { ...o, status: 'assigned', deliveryPersonId: currentUser.id } : o)); return; }
      await supabase.from('orders').update({ delivery_person_id: currentUser.id, status: 'assigned' }).eq('id', oid); 
      fetchData(); 
  };

  // Placeholder Admin Ops
  const banUser = async (uid: string, s: boolean) => { if(isMockMode) return; await supabase.from('profiles').update({ is_banned: s }).eq('id', uid); fetchData(); };
  const deleteUser = async (uid: string) => { if(isMockMode) return; await supabase.from('profiles').delete().eq('id', uid); fetchData(); };
  const approveVendor = async (vid: string, s: boolean) => { if(isMockMode) return; await supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid); fetchData(); };
  const approveDeliveryPerson = async (id: string, uid: string, status: string) => { if(isMockMode) return; await supabase.from('delivery_persons').update({ status }).eq('id', id); fetchData(); };
  const resetPassword = async (email: string) => ({ success: true });
  const updatePassword = async (pass: string) => ({ success: true });
  const showToast = (message: string, type: 'success'|'error'|'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => true;

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, deliveryPersons, users, isLoading, isDataLoading, cart, favorites, toast,
        login, signup, logout, resetPassword, updatePassword, switchRole,
        registerVendor, registerDeliveryPerson, refreshData: () => fetchData(),
        addProduct, updateProduct, updateProductStatus, deleteProduct,
        addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
        banUser, deleteUser, approveVendor, approveDeliveryPerson,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { useEffect, useState, ErrorInfo, ReactNode } from 'react';

// --- Error Boundary ---
interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error?: Error;
}

export class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  public state: ErrorBoundaryState = {
    hasError: false
  };

  public static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  public render() {
    if (this.state.hasError) {
      return (
        <div className="p-8 text-center bg-red-50 min-h-screen flex flex-col items-center justify-center">
          <div className="w-16 h-16 bg-red-100 text-red-500 rounded-full flex items-center justify-center mb-4 text-2xl">
             <i className="fa-solid fa-bug"></i>
          </div>
          <h1 className="text-xl font-bold text-gray-900 mb-2">Something went wrong</h1>
          <p className="text-gray-600 mb-6 text-sm max-w-md mx-auto">{this.state.error?.message}</p>
          <button 
            className="px-6 py-3 bg-red-600 text-white rounded-xl text-sm font-bold shadow-lg hover:bg-red-700 transition-colors"
            onClick={() => window.location.reload()}
          >
            Reload Application
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

// --- Avatar (New Component) ---
interface AvatarProps {
  src?: string | null;
  name: string;
  size?: 'sm' | 'md' | 'lg' | 'xl' | '2xl';
  className?: string;
  onClick?: () => void;
}

export const Avatar: React.FC<AvatarProps> = ({ src, name, size = 'md', className = '', onClick }) => {
  const [imgError, setImgError] = useState(false);

  // Reset error state if src changes
  useEffect(() => {
    setImgError(false);
  }, [src]);

  const initials = name
    ? name.split(' ').slice(0, 2).map(n => n[0]).join('').toUpperCase()
    : '?';

  // Size mappings
  const sizeClasses = {
