                                    >
                                        <i className="fa-solid fa-minus text-xs"></i>
                                    </button>
                                    <span className="flex-1 text-center font-bold text-gray-900">{quantity}</span>
                                    <button 
                                        onClick={() => handleQuantity(1)}
