                                        <button onClick={() => updateCartQuantity(item.productId, item.quantity - 1)} className="w-8 h-full flex items-center justify-center text-gray-500 hover:text-gray-900"><i className="fa-solid fa-minus text-[10px]"></i></button>
                                        <span className="text-xs font-bold w-6 text-center">{item.quantity}</span>
                                        <button onClick={() => updateCartQuantity(item.productId, item.quantity + 1)} className="w-8 h-full flex items-center justify-center text-gray-500 hover:text-gray-900"><i className="fa-solid fa-plus text-[10px]"></i></button>
                                    </div>
                                    <button onClick={() => removeFromCart(item.productId)} className="w-8 h-8 flex items-center justify-center text-gray-400 hover:text-red-500 transition-colors">
                                        <i className="fa-solid fa-trash text-sm"></i>
                                    </button>
                                </div>
                            </div>
                        </Card>
                    ))
                )}

                {cart.length > 0 && (
                    <div className="mt-6 pt-4 border-t border-gray-200">
                        <div className="flex justify-between items-center mb-2">
                            <span className="text-gray-500 text-sm">Subtotal</span>
                            <span className="font-bold text-gray-900">₵{subtotal.toFixed(2)}</span>
                        </div>
                        <p className="text-xs text-gray-400 mb-6 text-right">Delivery fees calculated at checkout</p>

                        <Button fullWidth size="lg" onClick={() => navigate('/buyer/checkout')} className="shadow-xl shadow-primary/20">
                            Proceed to Pay
                        </Button>
                    </div>
                )}
             </div>
        </div>
    );
};

export const Checkout: React.FC = () => {
    const { cart, placeOrder, currentUser, signup, login } = useApp();
    const navigate = useNavigate();
    const [method, setMethod] = useState<'delivery' | 'pickup'>('delivery');
    const [isPlacing, setIsPlacing] = useState(false);
    const [guestEmail, setGuestEmail] = useState('');
    const [deliveryFee, setDeliveryFee] = useState(10); 

    useEffect(() => {
        if (method === 'pickup') {
            setDeliveryFee(0);
        } else {
            setDeliveryFee(15.00); 
        }
    }, [method]);

    const handleOrder = async () => {
        if (!currentUser && !guestEmail) { alert("Email required for guest checkout"); return; }

        setIsPlacing(true);

        try {
            // Handle Guest: Create Shadow Account
            if (!currentUser) {
                // Try to create shadow account
                const shadowPass = 'guest123'; 
                const regRes = await signup(guestEmail, shadowPass, 'Guest User', 'buyer');

                if (!regRes.success) {
                    // If exists, try to log in (assuming they are a returning guest who knows this implicit flow or we just grab the ID if we could, but we can't easily without password. 
                    // So we prompt them to login if registration fails due to exists.)
                     const loginRes = await login(guestEmail, shadowPass);
                     if (!loginRes.success) {
                         alert("This email is already registered. Please Login first.");
                         setIsPlacing(false);
                         return;
                     }
                }
            }

            // Place Order
            await placeOrder(method, deliveryFee);
            setTimeout(() => { 
                setIsPlacing(false); 
                navigate('/buyer/orders'); 
            }, 2000);

        } catch (e) {
            console.error(e);
            setIsPlacing(false);
            alert("Checkout failed. Please try again.");
        }
    };

    const subtotal = cart.reduce((sum, item) => sum + (item.product.price * item.quantity), 0);
    const total = subtotal + deliveryFee;

    return (
        <div className="p-4 min-h-screen bg-gray-50 pb-32 animate-fade-in pb-safe">
            <h1 className="text-2xl font-display font-bold mb-6">Checkout</h1>

            {!currentUser && (
                <Card className="p-4 mb-4">
                    <h3 className="font-bold text-sm mb-2">Guest Checkout</h3>
                    <Input label="Email Address" value={guestEmail} onChange={e => setGuestEmail(e.target.value)} placeholder="Enter email for receipt" />
                    <p className="text-xs text-gray-400 mt-2">We'll create a temporary account for you to track this order.</p>
                </Card>
            )}

            <div className="grid grid-cols-2 gap-4 mb-6">
                <div onClick={() => setMethod('delivery')} className={`p-4 rounded-xl border-2 cursor-pointer text-center ${method === 'delivery' ? 'border-primary bg-blue-50 text-primary' : 'border-transparent bg-white'}`}>
                    <i className="fa-solid fa-motorcycle text-xl mb-2"></i>
                    <p className="font-bold text-sm">Delivery</p>
                    <p className="text-xs">₵{deliveryFee}</p>
                </div>
                <div onClick={() => setMethod('pickup')} className={`p-4 rounded-xl border-2 cursor-pointer text-center ${method === 'pickup' ? 'border-primary bg-blue-50 text-primary' : 'border-transparent bg-white'}`}>
                    <i className="fa-solid fa-person-walking text-xl mb-2"></i>
                    <p className="font-bold text-sm">Pickup</p>
                    <p className="text-xs">Free</p>
                </div>
            </div>

            <Card className="p-5">
                <h3 className="font-bold mb-4">Summary</h3>
                {cart.map(i => <div key={i.productId} className="flex justify-between text-sm mb-2"><span>{i.product.title} x{i.quantity}</span><span>₵{i.product.price * i.quantity}</span></div>)}
                <div className="border-t border-dashed my-4"></div>
                <div className="flex justify-between text-sm"><span>Subtotal</span><span>₵{subtotal.toFixed(2)}</span></div>
                <div className="flex justify-between text-sm"><span>Fee</span><span>₵{deliveryFee.toFixed(2)}</span></div>
                <div className="flex justify-between font-bold text-lg mt-2"><span>Total</span><span>₵{total.toFixed(2)}</span></div>
            </Card>

            <div className="fixed bottom-0 left-0 right-0 p-4 bg-white border-t border-gray-100">
                <Button fullWidth size="lg" onClick={handleOrder} disabled={isPlacing}>
                    {isPlacing ? 'Processing Order...' : `Pay ₵${total.toFixed(2)}`}
                </Button>
            </div>
        </div>
    );
};

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Product, Vendor, Order, CartItem, DeliveryPerson, Role, OrderStatus } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { INITIAL_LOCATION_CACHE } from './constants';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  deliveryPersons: DeliveryPerson[];
  users: User[];
  isLoading: boolean;
  isDataLoading: boolean;
  favorites: string[];
  toast: ToastMessage | null;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role) => Promise<{success: boolean, error?: string}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerDeliveryPerson: (data: Partial<DeliveryPerson>) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveDeliveryPerson: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// Helper to safely write to localStorage without crashing app if full
const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [deliveryPersons, setDeliveryPersons] = useState<DeliveryPerson[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // Keep small items in Storage
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // State Persistence (Only for small items)
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // CRITICAL FIX: CLEAN UP BLOATED STORAGE ON MOUNT
  useEffect(() => {
      try {
          localStorage.removeItem('lynqed_products');
          localStorage.removeItem('lynqed_vendors');
          localStorage.removeItem('lynqed_orders');
          localStorage.removeItem('lynqed_drivers');
      } catch(e) {
          console.error("Cleanup failed", e);
      }
  }, []);

  // Refs to hold latest state for event listeners to avoid dependency loops
  const vendorsRef = useRef(vendors);
  const currentUserRef = useRef(currentUser);
  const currentRoleRef = useRef(currentRole);

  useEffect(() => { vendorsRef.current = vendors; }, [vendors]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);
  useEffect(() => { currentRoleRef.current = currentRole; }, [currentRole]);

  // Audio Notification Helper
  const playNotificationSound = () => {
      try {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          if (!AudioContext) return;

          const ctx = new AudioContext();
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();

          osc.connect(gain);
          gain.connect(ctx.destination);

          osc.type = 'sine';
          osc.frequency.setValueAtTime(500, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1000, ctx.currentTime + 0.1);

          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);

          osc.start();
          osc.stop(ctx.currentTime + 0.5);
      } catch (e) {
          console.error("Audio play failed", e);
      }
  };

  // Init App Effect
  useEffect(() => {
    initApp();

    // Realtime subscriptions
    const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();

    const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
          fetchData();

          // Enhanced Notification for Vendors using Refs to avoid closure staleness
          if (payload.eventType === 'INSERT' && currentRoleRef.current === 'vendor') {
              const newOrder = payload.new as Order;
              const myVendorId = vendorsRef.current.find(v => v.userId === currentUserRef.current?.id)?.vendorId;

              if (myVendorId && newOrder.vendorId === myVendorId) {
                  playNotificationSound();
                  setToast({ message: "🔔 New Order Received!", type: "info" });
                  if (Notification.permission === 'granted') {
                      new Notification("New Order", { body: `Order received for ₵${newOrder.total}` });
                  }
              }
          }
      }).subscribe();

    return () => {
        supabase.removeChannel(productSub);
        supabase.removeChannel(orderSub);
    };
  }, []); 

  const initApp = async () => {
      await checkSession();
      fetchData();
  };

  const checkSession = async () => {
      try {
          const { data: { session } } = await supabase.auth.getSession();
          if (session?.user) {
              await fetchUserProfile(session.user.id);
          } else {
              setCurrentUser(null);
              setCurrentRole('guest');
          }
      } catch (e) { console.error(e); } 
      finally { setIsLoading(false); }
  };

  const fetchUserProfile = async (userId: string) => {
      try {
          // Persisted role from storage for quick check
          const persistedRole = localStorage.getItem('lynqed_role') as Role;

          const { data } = await supabase.from('profiles').select('*').eq('id', userId).single();

          if (data) {
              // Map DB snake_case to CamelCase if needed
              const isBanned = data.isBanned ?? data.is_banned ?? false;

              if (isBanned) {
                  await logout();
                  alert("Account Suspended");
                  return null;
              }
              const user: User = { 
                  ...data, 
                  isBanned: isBanned,
                  roles: data.roles || ['buyer'] 
              };
              setCurrentUser(user);

              // FORCE ADMIN ROLE if user is admin, ignoring local storage drift
              if (user.roles.includes('admin')) {
                  setCurrentRole('admin');
                  safeSetItem('lynqed_role', 'admin');
              } 
              // Otherwise try to respect last used role if valid
              else if (persistedRole && user.roles.includes(persistedRole)) {
                  setCurrentRole(persistedRole);
              } 
              // Fallback based on available roles
              else {
                  if (user.roles.includes('vendor')) setCurrentRole('vendor');
                  else if (user.roles.includes('deliveryPerson')) setCurrentRole('deliveryPerson');
                  else setCurrentRole('buyer');
              }
              return user;
          }
      } catch (e) {
          console.error("Profile fetch error", e);
      }
      return null;
  };

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, orderBy?: string) => {
             try {
                let query = supabase.from(table).select('*');
                if (orderBy) query = query.order(orderBy, { ascending: false });
                const { data, error } = await query;
                return error ? null : data;
             } catch { return null; }
          };

          const [pData, vData, oData, dData] = await Promise.all([
              fetchSafely('products', 'created_at'),
              fetchSafely('vendors'),
              fetchSafely('orders', 'created_at'),
              fetchSafely('delivery_persons')
          ]);

          if (pData) setProducts(pData.map((p: any) => ({
              ...p,
              vendorId: p.vendorId || p.vendor_id || p.vendorid, 
              contactPhone: p.contactPhone || p.contact_phone,
              // Other fields are usually snake_case matching simple keys or are handled automatically
          })) as Product[]);

          if (vData) {
              setVendors(vData.map((v: any) => ({
                  ...v,
                  id: v.id, // Capture Database PK
                  vendorId: v.vendorId || v.vendor_id || v.vendorid, 
                  storeName: v.storeName || v.store_name,
                  storeDescription: v.storeDescription || v.store_description,
                  storeAvatarUrl: v.storeAvatarUrl || v.store_avatar_url,
                  userId: v.userId || v.user_id,
                  isApproved: v.isApproved ?? v.is_approved ?? v.isapproved
              })) as Vendor[]);
          }

          if (oData) {
              setOrders(oData.map((o: any) => ({
                  ...o, 
                  vendorId: o.vendorId || o.vendor_id,
                  buyerId: o.buyerId || o.buyer_id,
                  deliveryPersonId: o.deliveryPersonId || o.delivery_person_id,
                  deliveryFee: o.deliveryFee || o.delivery_fee,
                  deliveryOption: o.deliveryOption || o.delivery_option,
                  createdAt: o.createdAt || o.created_at,
                  items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items
              })) as Order[]);
          }
          if (dData) setDeliveryPersons(dData.map((d: any) => ({
             ...d,
             userId: d.userId || d.user_id,
             fullName: d.fullName || d.full_name,
             vehicleType: d.vehicleType || d.vehicle_type,
          })) as DeliveryPerson[]);

          if (localStorage.getItem('lynqed_role') === 'admin') {
              const uData = await fetchSafely('profiles');
              if (uData) setUsers(uData.map((u:any) => ({
                  ...u,
                  isBanned: u.isBanned ?? u.is_banned ?? false
              })) as any);
          }
      } catch (e) { console.error(e); } 
      finally { setIsDataLoading(false); }
  };

  // Auth Functions (Login, Signup, Logout, Reset...)
  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });
      if (error) return { success: false, error: error.message };
      if (data.user) {
          const user = await fetchUserProfile(data.user.id);
          fetchData();

          let role: Role = 'buyer';
          if (user) {
              const persistedRole = localStorage.getItem('lynqed_role') as Role;
              if (persistedRole && user.roles.includes(persistedRole)) {
                  role = persistedRole;
              } else {
                   if (user.roles.includes('admin')) role = 'admin';
                   else if (user.roles.includes('vendor')) role = 'vendor';
                   else if (user.roles.includes('deliveryPerson')) role = 'deliveryPerson';
              }
          }
          return { success: true, role }; 
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName, roles: [role] } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           await supabase.from('profiles').insert({ id: data.user.id, email, name: fullName, roles: [role] });
           await login(email, password);
           return { success: true };
      }
      return { success: false };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  const resetPassword = async (email: string) => { return { success: true }; };
  const updatePassword = async (pass: string) => { return { success: true }; };
  const switchRole = (role: Role) => { if(currentUser?.roles.includes(role)) setCurrentRole(role); };

  // Utils
  const showToast = (message: string, type: 'success'|'error'|'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => (await Notification.requestPermission()) === 'granted';

  // --- STORAGE UPLOAD HELPER ---
  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileExt = file.name.split('.').pop();
          const fileName = `${Math.random().toString(36).substring(2, 15)}_${Date.now()}.${fileExt}`;
          const filePath = `${folder}/${fileName}`;

          const { error: uploadError } = await supabase.storage
              .from('lynqed-assets')
              .upload(filePath, file);

          if (uploadError) {
              console.error('Upload error:', uploadError);
              showToast(`Upload failed: ${uploadError.message}`, 'error');
              return null;
          }

          const { data } = supabase.storage.from('lynqed-assets').getPublicUrl(filePath);
          return data.publicUrl;
      } catch (error: any) {
          console.error('Storage error:', error);
          showToast('Image upload failed', 'error');
          return null;
      }
  };

  // Specific Actions
  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      try {
          // Check for existing vendor profile for this user
          const { data: existing } = await supabase.from('vendors').select('id').eq('user_id', currentUser.id).maybeSingle();

          let error;

          if (existing) {
               console.log("Updating existing vendor profile");
               const { error: upError } = await supabase.from('vendors').update({
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl
               }).eq('user_id', currentUser.id);
               error = upError;
          } else {
               console.log("Creating new vendor profile");
               const { error: inError } = await supabase.from('vendors').insert({ 
                   vendor_id: `v-${Date.now()}`, 
                   user_id: currentUser.id, 
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl,
                   is_approved: false, 
                   rating: 5.0 
               });
               error = inError;
          }

          if (error) {
              console.error("Vendor Registration Error:", error);
              showToast(`Registration failed: ${error.message || 'Database error'}`, "error");
              return { success: false };
          } 

          showToast("Store profile saved successfully", "success"); 
          await fetchData();
          return { success: true };

      } catch (e: any) {
          console.error("Vendor Registration Exception:", e);
          showToast(`Unexpected error: ${e.message || e}`, "error");
          return { success: false };
      }
  };

  const registerDeliveryPerson = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      const { error } = await supabase.from('delivery_persons').insert({ 
          user_id: currentUser.id, 
          full_name: data.fullName,
          vehicle_type: data.vehicleType,
          status: 'pending' 
      });

      if (error) {
          console.error("Delivery Registration Error:", error);
          showToast(`Application failed: ${error.message}`, "error");
          return { success: false };
      }

      showToast("Rider application submitted", "success"); 
      fetchData();
      return { success: true };
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) {
          showToast("You must be logged in.", "error");
          return false;
      }

      // Try finding vendor in state first
      let v = vendors.find(v => v.userId === currentUser.id);

      // Fallback: Fetch directly from DB if missing in state (Sync issues)
      if (!v) {
          try {
             // Use maybeSingle to avoid throwing if not found
             const { data } = await supabase.from('vendors').select('*').eq('user_id', currentUser.id).maybeSingle();
             if(data) {
                 v = {
                     ...data,
                     vendorId: data.vendor_id,
                     userId: data.user_id,
                     // Minimal fields needed for FK constraint and logic
                     storeName: data.store_name || 'My Store',
                     storeDescription: '',
                     location: '',
                     isApproved: data.is_approved,
                     rating: 5
                 };
             }
          } catch(e) {
              console.error("Vendor fetch fallback failed", e);
          }
      }

      if(!v) {
          showToast("Vendor profile not found. Please set up your store.", "error");
          return false;
      }

      const { customCategory, vendorId, ...dbProduct } = prod;

      // Explicit snake_case mapping for DB insert
      const productPayload = {
          vendor_id: v.vendorId, // Use the resolved vendor ID
          title: dbProduct.title,
          description: dbProduct.description,
          price: dbProduct.price,
          currency: 'GHS', // Default to GHS
          category: dbProduct.category,
          images: dbProduct.images,
          stock: dbProduct.stock,
          status: 'pending',
          location: dbProduct.location,
          contact_phone: dbProduct.contactPhone
      };

      const { error } = await supabase.from('products').insert(productPayload);

      if (error) {
          console.error("Supabase Insert Error:", error);
          showToast(`Failed to add product: ${error.message}`, "error");
          return false;
      }

      showToast("Product submitted for approval", "success"); 
      fetchData(); 
      return true;
  };

  const updateProduct = async (id: string, data: any) => {
      const { customCategory, vendorId, contactPhone, ...rest } = data;

      // Map to snake_case for update
      const updatePayload = {
          ...rest,
          contact_phone: contactPhone
      };

      const { error } = await supabase.from('products').update(updatePayload).eq('id', id);

      if (error) {
          showToast("Update failed", "error");
          console.error(error);
      } else {
          showToast("Product updated", "success");
          fetchData();
      }
  };

  const deleteProduct = async (id: string) => { 
      const { error } = await supabase.from('products').delete().eq('id', id); 
      if (error) showToast("Delete failed: " + error.message, "error");
      else { showToast("Product deleted", "success"); fetchData(); }
  };

  const updateProductStatus = async (id: string, status: string) => { 
      const { error } = await supabase.from('products').update({status}).eq('id', id); 
      if (error) showToast("Status update failed", "error");
      else { showToast("Product updated", "success"); fetchData(); }
  };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);

  const toggleFavorite = (pid: string) => {
      const isFav = favorites.includes(pid);
      if (isFav) {
          setFavorites(prev => prev.filter(i => i !== pid));
          showToast("Removed from Wishlist", "info");
      } else {
          setFavorites(prev => [...prev, pid]);
          showToast("Added to Wishlist ❤️", "success");
      }
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });

      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);

              const { error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, 
                  vendor_id: vid, 
                  items, 
                  total: subtotal+fee, 
                  delivery_fee: fee, 
                  status: 'placed', 
                  delivery_option: option 
              });

              if (error) {
                 throw error;
              }
          }
          showToast("Order Placed!", "success"); 
          clearCart(); 
          fetchData();
      } catch (e: any) {
          console.error("Order failed:", e);
          showToast(`Order failed: ${e.message}`, "error");
      }
  };

  const updateOrderStatus = async (oid: string, status: string) => { await supabase.from('orders').update({status}).eq('id', oid); fetchData(); };
  const assignDelivery = async (oid: string) => { if(currentUser) await supabase.from('orders').update({delivery_person_id: currentUser.id, status: 'assigned'}).eq('id', oid); fetchData(); };

  // Admin Actions with Improved Error Handling and Snake Case mapping
  const banUser = async (uid: string, s: boolean) => { 
      try {
          const { error } = await supabase.from('profiles').update({ is_banned: s }).eq('id', uid); 
          if (error) throw error;
          showToast(s ? "User Banned" : "User Unbanned", "success");
          fetchData(); 
      } catch (e: any) {
          console.error("Ban failed", e);
          showToast("Action failed: " + e.message, "error");
      }
  };

  const deleteUser = async (uid: string) => { 
      try {
          const { error } = await supabase.from('profiles').delete().eq('id', uid); 
          if (error) throw error;
          showToast("User deleted", "success");
          fetchData(); 
      } catch (e: any) {
           showToast("Delete failed: " + e.message, "error");
      }
  };

  // ROBUST VENDOR APPROVAL - ID Based
  const approveVendor = async (vid: string, s: boolean) => { 
      // vid corresponds to the custom 'vendorId' string (e.g. v-123)
      // We first find the full vendor object to get its Database PK (id)
      const vendor = vendors.find(v => v.vendorId === vid);

      if (!vendor) {
          showToast("Error: Vendor not found in state", "error");
          return;
      }

      showToast("Updating vendor...", "info");

      try {
          let query;
          // Strategy 1: Use Database Primary Key (safest)
          if (vendor.id) {
               console.log(`Updating via DB PK: ${vendor.id}`);
               query = supabase.from('vendors').update({ is_approved: s }).eq('id', vendor.id);
          } else {
               // Strategy 2: Fallback to custom vendor_id column
               console.log(`Updating via vendor_id column: ${vid}`);
               query = supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid);
          }

          const { error } = await query;

          if (error) {
             // Retry with camelCase if snake_case failed (unlikely but possible if manually created)
             console.warn("Snake_case update failed, trying camelCase...", error);
             const { error: retryError } = await supabase.from('vendors').update({ isApproved: s }).eq(vendor.id ? 'id' : 'vendorId', vendor.id || vid);

             if (retryError) throw error; // Throw original error to see actual DB issue
          }

          await fetchData();
          showToast(s ? "Vendor Approved" : "Vendor Suspended", "success");
      } catch (err: any) {
          console.error("Approval Error Details:", err);
          showToast(`Failed: ${err.message || 'Check Console'}`, "error");
      }
  };

  const approveDeliveryPerson = async (id: string, uid: string, status: string) => { 
      try {
          const { error } = await supabase.from('delivery_persons').update({status}).eq('id', id);
          if (error) throw error;

          if(status === 'approved') {
              // Add role to user profile
               const { data } = await supabase.from('profiles').select('roles').eq('id', uid).single();
               if(data) {
                   const newRoles = [...(data.roles || []), 'deliveryPerson'];
                   // Use Set to ensure uniqueness just in case
                   const uniqueRoles = Array.from(new Set(newRoles));
                   await supabase.from('profiles').update({roles: uniqueRoles}).eq('id', uid);
               }
          }
          showToast("Rider updated", "success");
          fetchData(); 
      } catch (e: any) {
          console.error("Delivery approval failed", e);
          showToast("Action failed: " + e.message, "error");
      }
  };

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, deliveryPersons, users, isLoading, isDataLoading, cart, favorites, toast,
        login, signup, logout, resetPassword, updatePassword, switchRole,
        uploadFile, registerVendor, registerDeliveryPerson, refreshData: fetchData,
        addProduct, updateProduct, updateProductStatus, deleteProduct,
        addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
        banUser, deleteUser, approveVendor, approveDeliveryPerson,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Product, Vendor, Order, CartItem, DeliveryPerson, Role, OrderStatus } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { INITIAL_LOCATION_CACHE } from './constants';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  deliveryPersons: DeliveryPerson[];
  users: User[];
  isLoading: boolean;
  isDataLoading: boolean;
  favorites: string[];
  toast: ToastMessage | null;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role) => Promise<{success: boolean, error?: string}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerDeliveryPerson: (data: Partial<DeliveryPerson>) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveDeliveryPerson: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// Helper to safely write to localStorage without crashing app if full
const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [deliveryPersons, setDeliveryPersons] = useState<DeliveryPerson[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // Keep small items in Storage
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // State Persistence (Only for small items)
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // CRITICAL FIX: CLEAN UP BLOATED STORAGE ON MOUNT
  useEffect(() => {
      try {
          localStorage.removeItem('lynqed_products');
          localStorage.removeItem('lynqed_vendors');
          localStorage.removeItem('lynqed_orders');
          localStorage.removeItem('lynqed_drivers');
      } catch(e) {
          console.error("Cleanup failed", e);
      }
  }, []);

  // Refs to hold latest state for event listeners to avoid dependency loops
  const vendorsRef = useRef(vendors);
  const currentUserRef = useRef(currentUser);
  const currentRoleRef = useRef(currentRole);

  useEffect(() => { vendorsRef.current = vendors; }, [vendors]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);
  useEffect(() => { currentRoleRef.current = currentRole; }, [currentRole]);

  // Audio Notification Helper
  const playNotificationSound = () => {
      try {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          if (!AudioContext) return;

          const ctx = new AudioContext();
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();

          osc.connect(gain);
          gain.connect(ctx.destination);

          osc.type = 'sine';
          osc.frequency.setValueAtTime(500, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1000, ctx.currentTime + 0.1);

          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);

          osc.start();
          osc.stop(ctx.currentTime + 0.5);
      } catch (e) {
          console.error("Audio play failed", e);
      }
  };

  // Init App Effect
  useEffect(() => {
    initApp();

    // Realtime subscriptions
    const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();

    const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
          fetchData();

          // Enhanced Notification for Vendors using Refs to avoid closure staleness
          if (payload.eventType === 'INSERT' && currentRoleRef.current === 'vendor') {
              const newOrder = payload.new as Order;
              const myVendorId = vendorsRef.current.find(v => v.userId === currentUserRef.current?.id)?.vendorId;

              if (myVendorId && newOrder.vendorId === myVendorId) {
                  playNotificationSound();
                  setToast({ message: "🔔 New Order Received!", type: "info" });
                  if (Notification.permission === 'granted') {
                      new Notification("New Order", { body: `Order received for ₵${newOrder.total}` });
                  }
              }
          }
      }).subscribe();

    return () => {
        supabase.removeChannel(productSub);
        supabase.removeChannel(orderSub);
    };
  }, []); 

  const initApp = async () => {
      await checkSession();
      fetchData();
  };

  const checkSession = async () => {
      try {
          const { data: { session } } = await supabase.auth.getSession();
          if (session?.user) {
              await fetchUserProfile(session.user.id);
          } else {
              setCurrentUser(null);
              setCurrentRole('guest');
          }
      } catch (e) { console.error(e); } 
      finally { setIsLoading(false); }
  };

  const fetchUserProfile = async (userId: string) => {
      try {
          // Persisted role from storage for quick check
          const persistedRole = localStorage.getItem('lynqed_role') as Role;

          const { data } = await supabase.from('profiles').select('*').eq('id', userId).single();

          if (data) {
              // Map DB snake_case to CamelCase if needed
              const isBanned = data.isBanned ?? data.is_banned ?? false;

              if (isBanned) {
                  await logout();
                  alert("Account Suspended");
                  return null;
              }
              const user: User = { 
                  ...data, 
                  isBanned: isBanned,
                  roles: data.roles || ['buyer'] 
              };
              setCurrentUser(user);

              // FORCE ADMIN ROLE if user is admin, ignoring local storage drift
              if (user.roles.includes('admin')) {
                  setCurrentRole('admin');
                  safeSetItem('lynqed_role', 'admin');
              } 
              // Otherwise try to respect last used role if valid
              else if (persistedRole && user.roles.includes(persistedRole)) {
                  setCurrentRole(persistedRole);
              } 
              // Fallback based on available roles
              else {
                  if (user.roles.includes('vendor')) setCurrentRole('vendor');
                  else if (user.roles.includes('deliveryPerson')) setCurrentRole('deliveryPerson');
                  else setCurrentRole('buyer');
              }
              return user;
          }
      } catch (e) {
          console.error("Profile fetch error", e);
      }
      return null;
  };

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, orderBy?: string) => {
             try {
                let query = supabase.from(table).select('*');
                if (orderBy) query = query.order(orderBy, { ascending: false });
                const { data, error } = await query;
                return error ? null : data;
             } catch { return null; }
          };

          const [pData, vData, oData, dData] = await Promise.all([
              fetchSafely('products', 'created_at'),
              fetchSafely('vendors'),
              fetchSafely('orders', 'created_at'),
              fetchSafely('delivery_persons')
          ]);

          if (pData) setProducts(pData.map((p: any) => ({
              ...p,
              vendorId: p.vendorId || p.vendor_id || p.vendorid, 
              contactPhone: p.contactPhone || p.contact_phone,
              // Other fields are usually snake_case matching simple keys or are handled automatically
          })) as Product[]);

          if (vData) {
              setVendors(vData.map((v: any) => ({
                  ...v,
                  id: v.id, // Capture Database PK
                  vendorId: v.vendorId || v.vendor_id || v.vendorid, 
                  storeName: v.storeName || v.store_name,
                  storeDescription: v.storeDescription || v.store_description,
                  storeAvatarUrl: v.storeAvatarUrl || v.store_avatar_url,
                  userId: v.userId || v.user_id,
                  isApproved: v.isApproved ?? v.is_approved ?? v.isapproved
              })) as Vendor[]);
          }

          if (oData) {
              setOrders(oData.map((o: any) => ({
                  ...o, 
                  vendorId: o.vendorId || o.vendor_id,
                  buyerId: o.buyerId || o.buyer_id,
                  deliveryPersonId: o.deliveryPersonId || o.delivery_person_id,
                  deliveryFee: o.deliveryFee || o.delivery_fee,
                  deliveryOption: o.deliveryOption || o.delivery_option,
                  createdAt: o.createdAt || o.created_at,
                  items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items
              })) as Order[]);
          }
          if (dData) setDeliveryPersons(dData.map((d: any) => ({
             ...d,
             userId: d.userId || d.user_id,
             fullName: d.fullName || d.full_name,
             vehicleType: d.vehicleType || d.vehicle_type,
          })) as DeliveryPerson[]);

          if (localStorage.getItem('lynqed_role') === 'admin') {
              const uData = await fetchSafely('profiles');
              if (uData) setUsers(uData.map((u:any) => ({
                  ...u,
                  isBanned: u.isBanned ?? u.is_banned ?? false
              })) as any);
          }
      } catch (e) { console.error(e); } 
      finally { setIsDataLoading(false); }
  };

  // Auth Functions (Login, Signup, Logout, Reset...)
  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });
      if (error) return { success: false, error: error.message };
      if (data.user) {
          const user = await fetchUserProfile(data.user.id);
          fetchData();

          let role: Role = 'buyer';
          if (user) {
              const persistedRole = localStorage.getItem('lynqed_role') as Role;
              if (persistedRole && user.roles.includes(persistedRole)) {
                  role = persistedRole;
              } else {
                   if (user.roles.includes('admin')) role = 'admin';
                   else if (user.roles.includes('vendor')) role = 'vendor';
                   else if (user.roles.includes('deliveryPerson')) role = 'deliveryPerson';
              }
          }
          return { success: true, role }; 
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName, roles: [role] } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           await supabase.from('profiles').insert({ id: data.user.id, email, name: fullName, roles: [role] });
           await login(email, password);
           return { success: true };
      }
      return { success: false };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  const resetPassword = async (email: string) => { return { success: true }; };
  const updatePassword = async (pass: string) => { return { success: true }; };
  const switchRole = (role: Role) => { if(currentUser?.roles.includes(role)) setCurrentRole(role); };

  // Utils
  const showToast = (message: string, type: 'success'|'error'|'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => (await Notification.requestPermission()) === 'granted';

  // --- STORAGE UPLOAD HELPER ---
  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileExt = file.name.split('.').pop();
          const fileName = `${Math.random().toString(36).substring(2, 15)}_${Date.now()}.${fileExt}`;
          const filePath = `${folder}/${fileName}`;

          const { error: uploadError } = await supabase.storage
              .from('lynqed-assets')
              .upload(filePath, file);

          if (uploadError) {
              console.error('Upload error:', uploadError);
              showToast(`Upload failed: ${uploadError.message}`, 'error');
              return null;
          }

          const { data } = supabase.storage.from('lynqed-assets').getPublicUrl(filePath);
          return data.publicUrl;
      } catch (error: any) {
          console.error('Storage error:', error);
          showToast('Image upload failed', 'error');
          return null;
      }
  };

  // Specific Actions
  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      try {
          // Check for existing vendor profile for this user
          const { data: existing } = await supabase.from('vendors').select('id').eq('user_id', currentUser.id).maybeSingle();

          let error;

          if (existing) {
               console.log("Updating existing vendor profile");
               const { error: upError } = await supabase.from('vendors').update({
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl
               }).eq('user_id', currentUser.id);
               error = upError;
          } else {
               console.log("Creating new vendor profile");
               const { error: inError } = await supabase.from('vendors').insert({ 
                   vendor_id: `v-${Date.now()}`, 
                   user_id: currentUser.id, 
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl,
                   is_approved: false, 
                   rating: 5.0 
               });
               error = inError;
          }

          if (error) {
              console.error("Vendor Registration Error:", error);
              showToast(`Registration failed: ${error.message || 'Database error'}`, "error");
              return { success: false };
          } 

          showToast("Store profile saved successfully", "success"); 
          await fetchData();
          return { success: true };

      } catch (e: any) {
          console.error("Vendor Registration Exception:", e);
          showToast(`Unexpected error: ${e.message || e}`, "error");
          return { success: false };
      }
  };

  const registerDeliveryPerson = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      const { error } = await supabase.from('delivery_persons').insert({ 
          user_id: currentUser.id, 
          full_name: data.fullName,
          vehicle_type: data.vehicleType,
          status: 'pending' 
      });

      if (error) {
          console.error("Delivery Registration Error:", error);
          showToast(`Application failed: ${error.message}`, "error");
          return { success: false };
      }

      showToast("Rider application submitted", "success"); 
      fetchData();
      return { success: true };
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) {
          showToast("You must be logged in.", "error");
          return false;
      }

      // Try finding vendor in state first
      let v = vendors.find(v => v.userId === currentUser.id);

      // Fallback: Fetch directly from DB if missing in state (Sync issues)
      if (!v) {
          try {
             // Use maybeSingle to avoid throwing if not found
             const { data } = await supabase.from('vendors').select('*').eq('user_id', currentUser.id).maybeSingle();
             if(data) {
                 v = {
                     ...data,
                     vendorId: data.vendor_id,
                     userId: data.user_id,
                     // Minimal fields needed for FK constraint and logic
                     storeName: data.store_name || 'My Store',
                     storeDescription: '',
                     location: '',
                     isApproved: data.is_approved,
                     rating: 5
                 };
             }
          } catch(e) {
              console.error("Vendor fetch fallback failed", e);
          }
      }

      if(!v) {
          showToast("Vendor profile not found. Please set up your store.", "error");
          return false;
      }

      const { customCategory, vendorId, ...dbProduct } = prod;

      // Explicit snake_case mapping for DB insert
      const productPayload = {
          vendor_id: v.vendorId, // Use the resolved vendor ID
          title: dbProduct.title,
          description: dbProduct.description,
          price: dbProduct.price,
          currency: 'GHS', // Default to GHS
          category: dbProduct.category,
          images: dbProduct.images,
          stock: dbProduct.stock,
          status: 'pending',
          location: dbProduct.location,
          contact_phone: dbProduct.contactPhone
      };

      const { error } = await supabase.from('products').insert(productPayload);

      if (error) {
          console.error("Supabase Insert Error:", error);
          showToast(`Failed to add product: ${error.message}`, "error");
          return false;
      }

      showToast("Product submitted for approval", "success"); 
      fetchData(); 
      return true;
  };

  const updateProduct = async (id: string, data: any) => {
      const { customCategory, vendorId, contactPhone, ...rest } = data;

      // Map to snake_case for update
      const updatePayload = {
          ...rest,
          contact_phone: contactPhone
      };

      const { error } = await supabase.from('products').update(updatePayload).eq('id', id);

      if (error) {
          showToast("Update failed", "error");
          console.error(error);
      } else {
          showToast("Product updated", "success");
          fetchData();
      }
  };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);

  const toggleFavorite = (pid: string) => {
      const isFav = favorites.includes(pid);
      if (isFav) {
          setFavorites(prev => prev.filter(i => i !== pid));
          showToast("Removed from Wishlist", "info");
      } else {
          setFavorites(prev => [...prev, pid]);
          showToast("Added to Wishlist ❤️", "success");
      }
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });

      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);

              const { error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, 
                  vendor_id: vid, 
                  items, 
                  total: subtotal+fee, 
                  delivery_fee: fee, 
                  status: 'placed', 
                  delivery_option: option 
              });

              if (error) {
                 throw error;
              }
          }
          showToast("Order Placed!", "success"); 
          clearCart(); 
          fetchData();
      } catch (e: any) {
          console.error("Order failed:", e);
          showToast(`Order failed: ${e.message}`, "error");
      }
  };

  const updateOrderStatus = async (oid: string, status: string) => { await supabase.from('orders').update({status}).eq('id', oid); fetchData(); };
  const assignDelivery = async (oid: string) => { if(currentUser) await supabase.from('orders').update({delivery_person_id: currentUser.id, status: 'assigned'}).eq('id', oid); fetchData(); };

  // =========================================================
  // ADMIN ACTIONS - WITH VALIDATION & PERMISSION CHECKING
  // =========================================================

  const banUser = async (uid: string, s: boolean) => { 
      try {
          // Explicitly selecting data to ensure row was actually modified
          const { data, error } = await supabase.from('profiles').update({ is_banned: s }).eq('id', uid).select();

          if (error) throw error;
          if (!data || data.length === 0) {
              throw new Error("Permission denied or user not found. Check if you have Admin rights.");
          }

          showToast(s ? "User Banned" : "User Unbanned", "success");
          fetchData(); 
      } catch (e: any) {
          console.error("Ban failed", e);
          showToast("Action failed: " + e.message, "error");
      }
  };

  const deleteUser = async (uid: string) => { 
      try {
          const { data, error } = await supabase.from('profiles').delete().eq('id', uid).select();
          if (error) throw error;
          if (!data || data.length === 0) {
              throw new Error("Permission denied or user not found.");
          }
          showToast("User deleted", "success");
          fetchData(); 
      } catch (e: any) {
           showToast("Delete failed: " + e.message, "error");
      }
  };

  const approveVendor = async (vid: string, s: boolean) => { 
      const vendor = vendors.find(v => v.vendorId === vid);

      if (!vendor) {
          showToast("Error: Vendor not found in state", "error");
          return;
      }

      showToast(s ? "Approving vendor..." : "Suspending vendor...", "info");

      try {
          let query;
          // Strategy 1: Use Database Primary Key (safest)
          if (vendor.id) {
               query = supabase.from('vendors').update({ is_approved: s }).eq('id', vendor.id);
          } else {
               // Strategy 2: Fallback to custom vendor_id column
               query = supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid);
          }

          // Chain select to verify update
          const { data, error } = await query.select();

          if (error) {
             console.warn("Snake_case update failed, trying camelCase...", error);
             // Retry
             const { data: retryData, error: retryError } = await supabase.from('vendors').update({ isApproved: s }).eq(vendor.id ? 'id' : 'vendorId', vendor.id || vid).select();

             if (retryError) throw retryError;
             if (!retryData || retryData.length === 0) throw new Error("Update blocked. No rows modified.");
          } else if (!data || data.length === 0) {
               // Try strategy 3: Maybe the ID field was wrong, try vendor_id if we tried ID first
               if (vendor.id) {
                   console.log("Retrying with vendor_id column...");
                   const { data: vData, error: vError } = await supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid).select();
                   if (vError) throw vError;
                   if (!vData || vData.length === 0) throw new Error("Permission denied or vendor not found.");
               } else {
                   throw new Error("Permission denied or vendor not found.");
               }
          }

          await fetchData();
          showToast(s ? "Vendor Approved" : "Vendor Suspended", "success");
      } catch (err: any) {
          console.error("Approval Error Details:", err);
          showToast(`Failed: ${err.message}`, "error");
      }
  };

  const approveDeliveryPerson = async (id: string, uid: string, status: string) => { 
      try {
          const { data, error } = await supabase.from('delivery_persons').update({status}).eq('id', id).select();
          if (error) throw error;
          if (!data || data.length === 0) throw new Error("Permission denied or rider not found.");

          if(status === 'approved') {
               const { data: userData } = await supabase.from('profiles').select('roles').eq('id', uid).single();
               if(userData) {
                   const newRoles = [...(userData.roles || []), 'deliveryPerson'];
                   const uniqueRoles = Array.from(new Set(newRoles));
                   await supabase.from('profiles').update({roles: uniqueRoles}).eq('id', uid);
               }
          }
          showToast("Rider updated", "success");
          fetchData(); 
      } catch (e: any) {
          console.error("Delivery approval failed", e);
          showToast("Action failed: " + e.message, "error");
      }
  };

  const updateProductStatus = async (id: string, status: string) => { 
      try {
        const { data, error } = await supabase.from('products').update({status}).eq('id', id).select(); 
        if (error) throw error;
        if (!data || data.length === 0) throw new Error("Permission denied or product not found.");

        showToast(`Product ${status}`, "success"); 
        fetchData(); 
      } catch(e: any) {
        showToast("Update failed: " + e.message, "error");
      }
  };

  const deleteProduct = async (id: string) => { 
      try {
        const { data, error } = await supabase.from('products').delete().eq('id', id).select(); 
        if (error) throw error;
        if (!data || data.length === 0) throw new Error("Permission denied or product not found.");

        showToast("Product deleted", "success"); 
        fetchData(); 
      } catch(e: any) {
        showToast("Delete failed: " + e.message, "error");
      }
  };

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, deliveryPersons, users, isLoading, isDataLoading, cart, favorites, toast,
        login, signup, logout, resetPassword, updatePassword, switchRole,
        uploadFile, registerVendor, registerDeliveryPerson, refreshData: fetchData,
        addProduct, updateProduct, updateProductStatus, deleteProduct,
        addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
        banUser, deleteUser, approveVendor, approveDeliveryPerson,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Product, Vendor, Order, CartItem, DeliveryPerson, Role, OrderStatus } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { INITIAL_LOCATION_CACHE } from './constants';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  deliveryPersons: DeliveryPerson[];
  users: User[];
  isLoading: boolean;
  isDataLoading: boolean;
  favorites: string[];
  toast: ToastMessage | null;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role) => Promise<{success: boolean, error?: string}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerDeliveryPerson: (data: Partial<DeliveryPerson>) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveDeliveryPerson: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// Helper to safely write to localStorage without crashing app if full
const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [deliveryPersons, setDeliveryPersons] = useState<DeliveryPerson[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // Keep small items in Storage
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // State Persistence (Only for small items)
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // CRITICAL FIX: CLEAN UP BLOATED STORAGE ON MOUNT
  useEffect(() => {
      try {
          localStorage.removeItem('lynqed_products');
          localStorage.removeItem('lynqed_vendors');
          localStorage.removeItem('lynqed_orders');
          localStorage.removeItem('lynqed_drivers');
      } catch(e) {
          console.error("Cleanup failed", e);
      }
  }, []);

  // Refs to hold latest state for event listeners to avoid dependency loops
  const vendorsRef = useRef(vendors);
  const currentUserRef = useRef(currentUser);
  const currentRoleRef = useRef(currentRole);

  useEffect(() => { vendorsRef.current = vendors; }, [vendors]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);
  useEffect(() => { currentRoleRef.current = currentRole; }, [currentRole]);

  // Audio Notification Helper
  const playNotificationSound = () => {
      try {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          if (!AudioContext) return;

          const ctx = new AudioContext();
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();

          osc.connect(gain);
          gain.connect(ctx.destination);

          osc.type = 'sine';
          osc.frequency.setValueAtTime(500, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1000, ctx.currentTime + 0.1);

          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);

          osc.start();
          osc.stop(ctx.currentTime + 0.5);
      } catch (e) {
          console.error("Audio play failed", e);
      }
  };

  // Init App Effect
  useEffect(() => {
    initApp();

    // Realtime subscriptions
    const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();

    const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
          fetchData();

          // Enhanced Notification for Vendors using Refs to avoid closure staleness
          if (payload.eventType === 'INSERT' && currentRoleRef.current === 'vendor') {
              const newOrder = payload.new as any; // Using any to inspect raw snake_case payload if needed, but fetch calls re-map it

              // We refetch data, so we check vendorsRef
              const myVendorId = vendorsRef.current.find(v => v.userId === currentUserRef.current?.id)?.vendorId;

              // The real-time payload is in snake_case, so we access vendor_id
              if (myVendorId && newOrder.vendor_id === myVendorId) {
                  playNotificationSound();
                  setToast({ message: "🔔 New Order Received!", type: "info" });
                  if (Notification.permission === 'granted') {
                      new Notification("New Order", { body: `Order received for ₵${newOrder.total}` });
                  }
              }
          }
      }).subscribe();

    return () => {
        supabase.removeChannel(productSub);
        supabase.removeChannel(orderSub);
    };
  }, []); 

  const initApp = async () => {
      await checkSession();
      fetchData();
  };

  const checkSession = async () => {
      try {
          const { data: { session } } = await supabase.auth.getSession();
          if (session?.user) {
              await fetchUserProfile(session.user.id);
          } else {
              setCurrentUser(null);
              setCurrentRole('guest');
          }
      } catch (e) { console.error(e); } 
      finally { setIsLoading(false); }
  };

  const fetchUserProfile = async (userId: string) => {
      try {
          // Persisted role from storage for quick check
          const persistedRole = localStorage.getItem('lynqed_role') as Role;

          const { data } = await supabase.from('profiles').select('*').eq('id', userId).single();

          if (data) {
              // Map snake_case -> camelCase
              const isBanned = data.is_banned ?? false;

              if (isBanned) {
                  await logout();
                  alert("Account Suspended");
                  return null;
              }
              const user: User = { 
                  id: data.id,
                  name: data.name,
                  email: data.email,
                  roles: data.roles || ['buyer'],
                  avatarUrl: data.avatar_url,
                  defaultLocation: data.default_location,
                  isBanned: isBanned
              };
              setCurrentUser(user);

              // FORCE ADMIN ROLE if user is admin, ignoring local storage drift
              if (user.roles.includes('admin')) {
                  setCurrentRole('admin');
                  safeSetItem('lynqed_role', 'admin');
              } 
              // Otherwise try to respect last used role if valid
              else if (persistedRole && user.roles.includes(persistedRole)) {
                  setCurrentRole(persistedRole);
              } 
              // Fallback based on available roles
              else {
                  if (user.roles.includes('vendor')) setCurrentRole('vendor');
                  else if (user.roles.includes('deliveryPerson')) setCurrentRole('deliveryPerson');
                  else setCurrentRole('buyer');
              }
              return user;
          }
      } catch (e) {
          console.error("Profile fetch error", e);
      }
      return null;
  };

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, orderBy?: string) => {
             try {
                let query = supabase.from(table).select('*');
                if (orderBy) query = query.order(orderBy, { ascending: false });
                const { data, error } = await query;
                return error ? null : data;
             } catch { return null; }
          };

          const [pData, vData, oData, dData] = await Promise.all([
              fetchSafely('products', 'created_at'),
              fetchSafely('vendors'),
              fetchSafely('orders', 'created_at'),
              fetchSafely('delivery_persons')
          ]);

          if (pData) setProducts(pData.map((p: any) => ({
              ...p,
              // Map DB snake_case to TS camelCase
              vendorId: p.vendor_id,
              contactPhone: p.contact_phone,
          })) as Product[]);

          if (vData) {
              setVendors(vData.map((v: any) => ({
                  ...v,
                  id: v.id, 
                  vendorId: v.vendor_id, 
                  userId: v.user_id,
                  storeName: v.store_name,
                  storeDescription: v.store_description,
                  storeAvatarUrl: v.store_avatar_url,
                  contactPhone: v.contact_phone,
                  isApproved: v.is_approved
              })) as Vendor[]);
          }

          if (oData) {
              setOrders(oData.map((o: any) => ({
                  ...o, 
                  vendorId: o.vendor_id,
                  buyerId: o.buyer_id,
                  deliveryPersonId: o.delivery_person_id,
                  deliveryFee: o.delivery_fee,
                  deliveryOption: o.delivery_option,
                  locationCoordinates: o.location_coordinates,
                  createdAt: o.created_at,
                  items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items
              })) as Order[]);
          }
          if (dData) setDeliveryPersons(dData.map((d: any) => ({
             ...d,
             userId: d.user_id,
             fullName: d.full_name,
             vehicleType: d.vehicle_type,
             totalDeliveries: d.total_deliveries,
          })) as DeliveryPerson[]);

          if (localStorage.getItem('lynqed_role') === 'admin') {
              const uData = await fetchSafely('profiles');
              if (uData) setUsers(uData.map((u:any) => ({
                  id: u.id,
                  name: u.name,
                  email: u.email,
                  avatarUrl: u.avatar_url,
                  roles: u.roles,
                  defaultLocation: u.default_location,
                  isBanned: u.is_banned
              })) as any);
          }
      } catch (e) { console.error(e); } 
      finally { setIsDataLoading(false); }
  };

  // Auth Functions (Login, Signup, Logout, Reset...)
  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });
      if (error) return { success: false, error: error.message };
      if (data.user) {
          const user = await fetchUserProfile(data.user.id);
          fetchData();

          let role: Role = 'buyer';
          if (user) {
              const persistedRole = localStorage.getItem('lynqed_role') as Role;
              if (persistedRole && user.roles.includes(persistedRole)) {
                  role = persistedRole;
              } else {
                   if (user.roles.includes('admin')) role = 'admin';
                   else if (user.roles.includes('vendor')) role = 'vendor';
                   else if (user.roles.includes('deliveryPerson')) role = 'deliveryPerson';
              }
          }
          return { success: true, role }; 
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName, roles: [role] } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           await supabase.from('profiles').insert({ 
               id: data.user.id, 
               email, 
               name: fullName, 
               roles: [role],
               is_banned: false 
           });
           await login(email, password);
           return { success: true };
      }
      return { success: false };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  const resetPassword = async (email: string) => { return { success: true }; };
  const updatePassword = async (pass: string) => { return { success: true }; };
  const switchRole = (role: Role) => { if(currentUser?.roles.includes(role)) setCurrentRole(role); };

  // Utils
  const showToast = (message: string, type: 'success'|'error'|'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => (await Notification.requestPermission()) === 'granted';

  // --- STORAGE UPLOAD HELPER ---
  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileExt = file.name.split('.').pop();
          const fileName = `${Math.random().toString(36).substring(2, 15)}_${Date.now()}.${fileExt}`;
          const filePath = `${folder}/${fileName}`;

          const { error: uploadError } = await supabase.storage
              .from('lynqed-assets')
              .upload(filePath, file);

          if (uploadError) {
              console.error('Upload error:', uploadError);
              showToast(`Upload failed: ${uploadError.message}`, 'error');
              return null;
          }

          const { data } = supabase.storage.from('lynqed-assets').getPublicUrl(filePath);
          return data.publicUrl;
      } catch (error: any) {
          console.error('Storage error:', error);
          showToast('Image upload failed', 'error');
          return null;
      }
  };

  // Specific Actions
  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      try {
          // Check for existing vendor profile for this user
          const { data: existing } = await supabase.from('vendors').select('id').eq('user_id', currentUser.id).maybeSingle();

          let error;

          if (existing) {
               console.log("Updating existing vendor profile");
               const { error: upError } = await supabase.from('vendors').update({
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl
               }).eq('user_id', currentUser.id);
               error = upError;
          } else {
               console.log("Creating new vendor profile");
               const { error: inError } = await supabase.from('vendors').insert({ 
                   vendor_id: `v-${Date.now()}`, 
                   user_id: currentUser.id, 
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl,
                   is_approved: false, 
                   rating: 5.0 
               });
               error = inError;
          }

          if (error) {
              console.error("Vendor Registration Error:", error);
              showToast(`Registration failed: ${error.message || 'Database error'}`, "error");
              return { success: false };
          } 

          showToast("Store profile saved successfully", "success"); 
          await fetchData();
          return { success: true };

      } catch (e: any) {
          console.error("Vendor Registration Exception:", e);
          showToast(`Unexpected error: ${e.message || e}`, "error");
          return { success: false };
      }
  };

  const registerDeliveryPerson = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      const { error } = await supabase.from('delivery_persons').insert({ 
          user_id: currentUser.id, 
          full_name: data.fullName,
          vehicle_type: data.vehicleType,
          status: 'pending' 
      });

      if (error) {
          console.error("Delivery Registration Error:", error);
          showToast(`Application failed: ${error.message}`, "error");
          return { success: false };
      }

      showToast("Rider application submitted", "success"); 
      fetchData();
      return { success: true };
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) {
          showToast("You must be logged in.", "error");
          return false;
      }

      // Try finding vendor in state first
      let v = vendors.find(v => v.userId === currentUser.id);

      // Fallback: Fetch directly from DB if missing in state (Sync issues)
      if (!v) {
          try {
             // Use maybeSingle to avoid throwing if not found
             const { data } = await supabase.from('vendors').select('*').eq('user_id', currentUser.id).maybeSingle();
             if(data) {
                 v = {
                     ...data,
                     vendorId: data.vendor_id,
                     userId: data.user_id,
                     // Minimal fields needed for FK constraint and logic
                     storeName: data.store_name || 'My Store',
                     storeDescription: '',
                     location: '',
                     isApproved: data.is_approved,
                     rating: 5
                 };
             }
          } catch(e) {
              console.error("Vendor fetch fallback failed", e);
          }
      }

      if(!v) {
          showToast("Vendor profile not found. Please set up your store.", "error");
          return false;
      }

      const { customCategory, vendorId, ...dbProduct } = prod;

      // snake_case payload
      const productPayload = {
          vendor_id: v.vendorId, 
          title: dbProduct.title,
          description: dbProduct.description,
          price: dbProduct.price,
          currency: 'GHS',
          category: dbProduct.category,
          images: dbProduct.images,
          stock: dbProduct.stock,
          status: 'pending',
          location: dbProduct.location,
          contact_phone: dbProduct.contactPhone
      };

      const { error } = await supabase.from('products').insert(productPayload);

      if (error) {
          console.error("Supabase Insert Error:", error);
          showToast(`Failed to add product: ${error.message}`, "error");
          return false;
      }

      showToast("Product submitted for approval", "success"); 
      fetchData(); 
      return true;
  };

  const updateProduct = async (id: string, data: any) => {
      const { customCategory, vendorId, contactPhone, ...rest } = data;

      // Map to snake_case for update
      const updatePayload = {
          ...rest,
          contact_phone: contactPhone
      };

      const { error } = await supabase.from('products').update(updatePayload).eq('id', id);

      if (error) {
          showToast("Update failed", "error");
          console.error(error);
      } else {
          showToast("Product updated", "success");
          fetchData();
      }
  };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);

  const toggleFavorite = (pid: string) => {
      const isFav = favorites.includes(pid);
      if (isFav) {
          setFavorites(prev => prev.filter(i => i !== pid));
          showToast("Removed from Wishlist", "info");
      } else {
          setFavorites(prev => [...prev, pid]);
          showToast("Added to Wishlist ❤️", "success");
      }
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });

      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);

              const { error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, 
                  vendor_id: vid, 
                  items, 
                  total: subtotal+fee, 
                  delivery_fee: fee, 
                  status: 'placed', 
                  delivery_option: option 
              });

              if (error) {
                 throw error;
              }
          }
          showToast("Order Placed!", "success"); 
          clearCart(); 
          fetchData();
      } catch (e: any) {
          console.error("Order failed:", e);
          showToast(`Order failed: ${e.message}`, "error");
      }
  };

  const updateOrderStatus = async (oid: string, status: string) => { await supabase.from('orders').update({status}).eq('id', oid); fetchData(); };

  const assignDelivery = async (oid: string) => { 
      if(currentUser) await supabase.from('orders').update({
          delivery_person_id: currentUser.id, 
          status: 'assigned'
      }).eq('id', oid); 
      fetchData(); 
  };

  // =========================================================
  // ADMIN ACTIONS - STRICT SNAKE_CASE & VERIFICATION
  // =========================================================

  const banUser = async (uid: string, s: boolean) => { 
      try {
          const { data, error } = await supabase.from('profiles').update({ is_banned: s }).eq('id', uid).select();

          if (error) throw error;
          if (!data || data.length === 0) {
              throw new Error("Permission denied or user not found. Check if you have Admin rights.");
          }

          showToast(s ? "User Banned" : "User Unbanned", "success");
          fetchData(); 
      } catch (e: any) {
          console.error("Ban failed", e);
          showToast("Action failed: " + e.message, "error");
      }
  };

  const deleteUser = async (uid: string) => { 
      try {
          const { data, error } = await supabase.from('profiles').delete().eq('id', uid).select();
          if (error) throw error;
          if (!data || data.length === 0) {
              throw new Error("Permission denied or user not found.");
          }
          showToast("User deleted", "success");
          fetchData(); 
      } catch (e: any) {
           showToast("Delete failed: " + e.message, "error");
      }
  };

  const approveVendor = async (vid: string, s: boolean) => { 
      showToast(s ? "Approving vendor..." : "Suspending vendor...", "info");

      try {
          // Update using the unique vendor_id
          const { data, error } = await supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid).select();

          if (error) throw error;
          if (!data || data.length === 0) {
               throw new Error("Permission denied or vendor not found.");
          }

          await fetchData();
          showToast(s ? "Vendor Approved" : "Vendor Suspended", "success");
      } catch (err: any) {
          console.error("Approval Error Details:", err);
          showToast(`Failed: ${err.message}`, "error");
      }
  };

  const approveDeliveryPerson = async (id: string, uid: string, status: string) => { 
      try {
          const { data, error } = await supabase.from('delivery_persons').update({status}).eq('id', id).select();
          if (error) throw error;
          if (!data || data.length === 0) throw new Error("Permission denied or rider not found.");

          if(status === 'approved') {
               const { data: userData } = await supabase.from('profiles').select('roles').eq('id', uid).single();
               if(userData) {
                   const newRoles = [...(userData.roles || []), 'deliveryPerson'];
                   const uniqueRoles = Array.from(new Set(newRoles));
                   await supabase.from('profiles').update({roles: uniqueRoles}).eq('id', uid);
               }
          }
          showToast("Rider updated", "success");
          fetchData(); 
      } catch (e: any) {
          console.error("Delivery approval failed", e);
          showToast("Action failed: " + e.message, "error");
      }
  };

  const updateProductStatus = async (id: string, status: string) => { 
      try {
        const { data, error } = await supabase.from('products').update({status}).eq('id', id).select(); 
        if (error) throw error;
        if (!data || data.length === 0) throw new Error("Permission denied or product not found.");

        showToast(`Product ${status}`, "success"); 
        fetchData(); 
      } catch(e: any) {
        showToast("Update failed: " + e.message, "error");
      }
  };

  const deleteProduct = async (id: string) => { 
      try {
        const { data, error } = await supabase.from('products').delete().eq('id', id).select(); 
        if (error) throw error;
        if (!data || data.length === 0) throw new Error("Permission denied or product not found.");

        showToast("Product deleted", "success"); 
        fetchData(); 
      } catch(e: any) {
        showToast("Delete failed: " + e.message, "error");
      }
  };

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, deliveryPersons, users, isLoading, isDataLoading, cart, favorites, toast,
        login, signup, logout, resetPassword, updatePassword, switchRole,
        uploadFile, registerVendor, registerDeliveryPerson, refreshData: fetchData,
        addProduct, updateProduct, updateProductStatus, deleteProduct,
        addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
        banUser, deleteUser, approveVendor, approveDeliveryPerson,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Product, Vendor, Order, CartItem, DeliveryPerson, Role, OrderStatus } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { INITIAL_LOCATION_CACHE } from './constants';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  deliveryPersons: DeliveryPerson[];
  users: User[];
  isLoading: boolean;
  isDataLoading: boolean;
  favorites: string[];
  toast: ToastMessage | null;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role) => Promise<{success: boolean, error?: string}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerDeliveryPerson: (data: Partial<DeliveryPerson>) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveDeliveryPerson: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// Helper to safely write to localStorage without crashing app if full
const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [deliveryPersons, setDeliveryPersons] = useState<DeliveryPerson[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // Keep small items in Storage
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // State Persistence (Only for small items)
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // CRITICAL FIX: CLEAN UP BLOATED STORAGE ON MOUNT
  useEffect(() => {
      try {
          localStorage.removeItem('lynqed_products');
          localStorage.removeItem('lynqed_vendors');
          localStorage.removeItem('lynqed_orders');
          localStorage.removeItem('lynqed_drivers');
      } catch(e) {
          console.error("Cleanup failed", e);
      }
  }, []);

  // Refs to hold latest state for event listeners to avoid dependency loops
  const vendorsRef = useRef(vendors);
  const currentUserRef = useRef(currentUser);
  const currentRoleRef = useRef(currentRole);

  useEffect(() => { vendorsRef.current = vendors; }, [vendors]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);
  useEffect(() => { currentRoleRef.current = currentRole; }, [currentRole]);

  // Audio Notification Helper
  const playNotificationSound = () => {
      try {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          if (!AudioContext) return;

          const ctx = new AudioContext();
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();

          osc.connect(gain);
          gain.connect(ctx.destination);

          osc.type = 'sine';
          osc.frequency.setValueAtTime(500, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1000, ctx.currentTime + 0.1);

          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);

          osc.start();
          osc.stop(ctx.currentTime + 0.5);
      } catch (e) {
          console.error("Audio play failed", e);
      }
  };

  // Init App Effect
  useEffect(() => {
    initApp();

    // Realtime subscriptions
    const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();

    const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
          fetchData();

          // Enhanced Notification for Vendors using Refs to avoid closure staleness
          if (payload.eventType === 'INSERT' && currentRoleRef.current === 'vendor') {
              const newOrder = payload.new as any; // Using any to inspect raw snake_case payload if needed, but fetch calls re-map it

              // We refetch data, so we check vendorsRef
              const myVendorId = vendorsRef.current.find(v => v.userId === currentUserRef.current?.id)?.vendorId;

              // The real-time payload is in snake_case, so we access vendor_id
              if (myVendorId && newOrder.vendor_id === myVendorId) {
                  playNotificationSound();
                  setToast({ message: "🔔 New Order Received!", type: "info" });
                  if (Notification.permission === 'granted') {
                      new Notification("New Order", { body: `Order received for ₵${newOrder.total}` });
                  }
              }
          }
      }).subscribe();

    return () => {
        supabase.removeChannel(productSub);
        supabase.removeChannel(orderSub);
    };
  }, []); 

  const initApp = async () => {
      await checkSession();
      fetchData();
  };

  const checkSession = async () => {
      try {
          const { data: { session } } = await supabase.auth.getSession();
          if (session?.user) {
              await fetchUserProfile(session.user.id);
          } else {
              setCurrentUser(null);
              setCurrentRole('guest');
          }
      } catch (e) { console.error(e); } 
      finally { setIsLoading(false); }
  };

  const fetchUserProfile = async (userId: string) => {
      try {
          // Persisted role from storage for quick check
          const persistedRole = localStorage.getItem('lynqed_role') as Role;

          const { data } = await supabase.from('profiles').select('*').eq('id', userId).single();

          if (data) {
              // Map snake_case -> camelCase
              const isBanned = data.is_banned ?? false;

              if (isBanned) {
                  await logout();
                  alert("Account Suspended");
                  return null;
              }
              const user: User = { 
                  id: data.id,
                  name: data.name,
                  email: data.email,
                  roles: data.roles || ['buyer'],
                  avatarUrl: data.avatar_url,
                  defaultLocation: data.default_location,
                  isBanned: isBanned
              };
              setCurrentUser(user);

              // FORCE ADMIN ROLE if user is admin, ignoring local storage drift
              if (user.roles.includes('admin')) {
                  setCurrentRole('admin');
                  safeSetItem('lynqed_role', 'admin');
              } 
              // Otherwise try to respect last used role if valid
              else if (persistedRole && user.roles.includes(persistedRole)) {
                  setCurrentRole(persistedRole);
              } 
              // Fallback based on available roles
              else {
                  if (user.roles.includes('vendor')) setCurrentRole('vendor');
                  else if (user.roles.includes('deliveryPerson')) setCurrentRole('deliveryPerson');
                  else setCurrentRole('buyer');
              }
              return user;
          }
      } catch (e) {
          console.error("Profile fetch error", e);
      }
      return null;
  };

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, orderBy?: string) => {
             try {
                let query = supabase.from(table).select('*');
                if (orderBy) query = query.order(orderBy, { ascending: false });
                const { data, error } = await query;
                return error ? null : data;
             } catch { return null; }
          };

          const [pData, vData, oData, dData] = await Promise.all([
              fetchSafely('products', 'created_at'),
              fetchSafely('vendors'),
              fetchSafely('orders', 'created_at'),
              fetchSafely('delivery_persons')
          ]);

          if (pData) setProducts(pData.map((p: any) => ({
              ...p,
              // Map DB snake_case to TS camelCase
              vendorId: p.vendor_id,
              contactPhone: p.contact_phone,
          })) as Product[]);

          if (vData) {
              setVendors(vData.map((v: any) => ({
                  ...v,
                  id: v.id, 
                  vendorId: v.vendor_id, 
                  userId: v.user_id,
                  storeName: v.store_name,
                  storeDescription: v.store_description,
                  storeAvatarUrl: v.store_avatar_url,
                  contactPhone: v.contact_phone,
                  isApproved: v.is_approved
              })) as Vendor[]);
          }

          if (oData) {
              setOrders(oData.map((o: any) => ({
                  ...o, 
                  vendorId: o.vendor_id,
                  buyerId: o.buyer_id,
                  deliveryPersonId: o.delivery_person_id,
                  deliveryFee: o.delivery_fee,
                  deliveryOption: o.delivery_option,
                  locationCoordinates: o.location_coordinates,
                  createdAt: o.created_at,
                  items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items
              })) as Order[]);
          }
          if (dData) setDeliveryPersons(dData.map((d: any) => ({
             ...d,
             userId: d.user_id,
             fullName: d.full_name,
             vehicleType: d.vehicle_type,
             totalDeliveries: d.total_deliveries,
          })) as DeliveryPerson[]);

          if (localStorage.getItem('lynqed_role') === 'admin') {
              const uData = await fetchSafely('profiles');
              if (uData) setUsers(uData.map((u:any) => ({
                  id: u.id,
                  name: u.name,
                  email: u.email,
                  avatarUrl: u.avatar_url,
                  roles: u.roles,
                  defaultLocation: u.default_location,
                  isBanned: u.is_banned
              })) as any);
          }
      } catch (e) { console.error(e); } 
      finally { setIsDataLoading(false); }
  };

  // Auth Functions (Login, Signup, Logout, Reset...)
  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });

      if (error) {
          // Improve UX: Check if user actually exists to give specific feedback
          try {
              const { data: userProfile } = await supabase.from('profiles').select('id').eq('email', email).maybeSingle();
              if (!userProfile) {
                  return { success: false, error: "Account does not exist. Please register." };
              }
          } catch (e) {
              // Fallthrough to generic error
          }
          return { success: false, error: "Invalid password. Please try again." };
      }

      if (data.user) {
          const user = await fetchUserProfile(data.user.id);
          fetchData();

          let role: Role = 'buyer';
          if (user) {
              const persistedRole = localStorage.getItem('lynqed_role') as Role;
              if (persistedRole && user.roles.includes(persistedRole)) {
                  role = persistedRole;
              } else {
                   if (user.roles.includes('admin')) role = 'admin';
                   else if (user.roles.includes('vendor')) role = 'vendor';
                   else if (user.roles.includes('deliveryPerson')) role = 'deliveryPerson';
              }
          }
          return { success: true, role }; 
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName, roles: [role] } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           await supabase.from('profiles').insert({ 
               id: data.user.id, 
               email, 
               name: fullName, 
               roles: [role],
               is_banned: false 
           });
           await login(email, password);
           return { success: true };
      }
      return { success: false };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  const resetPassword = async (email: string) => { return { success: true }; };
  const updatePassword = async (pass: string) => { return { success: true }; };
  const switchRole = (role: Role) => { if(currentUser?.roles.includes(role)) setCurrentRole(role); };

  // Utils
  const showToast = (message: string, type: 'success'|'error'|'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => (await Notification.requestPermission()) === 'granted';

  // --- STORAGE UPLOAD HELPER ---
  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileExt = file.name.split('.').pop();
          const fileName = `${Math.random().toString(36).substring(2, 15)}_${Date.now()}.${fileExt}`;
          const filePath = `${folder}/${fileName}`;

          const { error: uploadError } = await supabase.storage
              .from('lynqed-assets')
              .upload(filePath, file);

          if (uploadError) {
              console.error('Upload error:', uploadError);
              showToast(`Upload failed: ${uploadError.message}`, 'error');
              return null;
          }

          const { data } = supabase.storage.from('lynqed-assets').getPublicUrl(filePath);
          return data.publicUrl;
      } catch (error: any) {
          console.error('Storage error:', error);
          showToast('Image upload failed', 'error');
          return null;
      }
  };

  // Specific Actions
  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      try {
          // Check for existing vendor profile for this user
          const { data: existing } = await supabase.from('vendors').select('id').eq('user_id', currentUser.id).maybeSingle();

          let error;

          if (existing) {
               console.log("Updating existing vendor profile");
               const { error: upError } = await supabase.from('vendors').update({
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl
               }).eq('user_id', currentUser.id);
               error = upError;
          } else {
               console.log("Creating new vendor profile");
               const { error: inError } = await supabase.from('vendors').insert({ 
                   vendor_id: `v-${Date.now()}`, 
                   user_id: currentUser.id, 
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl,
                   is_approved: false, 
                   rating: 5.0 
               });
               error = inError;
          }

          if (error) {
              console.error("Vendor Registration Error:", error);
              showToast(`Registration failed: ${error.message || 'Database error'}`, "error");
              return { success: false };
          } 

          showToast("Store profile saved successfully", "success"); 
          await fetchData();
          return { success: true };

      } catch (e: any) {
          console.error("Vendor Registration Exception:", e);
          showToast(`Unexpected error: ${e.message || e}`, "error");
          return { success: false };
      }
  };

  const registerDeliveryPerson = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      const { error } = await supabase.from('delivery_persons').insert({ 
          user_id: currentUser.id, 
          full_name: data.fullName,
          vehicle_type: data.vehicleType,
          status: 'pending' 
      });

      if (error) {
          console.error("Delivery Registration Error:", error);
          showToast(`Application failed: ${error.message}`, "error");
          return { success: false };
      }

      showToast("Rider application submitted", "success"); 
      fetchData();
      return { success: true };
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) {
          showToast("You must be logged in.", "error");
          return false;
      }

      // Try finding vendor in state first
      let v = vendors.find(v => v.userId === currentUser.id);

      // Fallback: Fetch directly from DB if missing in state (Sync issues)
      if (!v) {
          try {
             // Use maybeSingle to avoid throwing if not found
             const { data } = await supabase.from('vendors').select('*').eq('user_id', currentUser.id).maybeSingle();
             if(data) {
                 v = {
                     ...data,
                     vendorId: data.vendor_id,
                     userId: data.user_id,
                     // Minimal fields needed for FK constraint and logic
                     storeName: data.store_name || 'My Store',
                     storeDescription: '',
                     location: '',
                     isApproved: data.is_approved,
                     rating: 5
                 };
             }
          } catch(e) {
              console.error("Vendor fetch fallback failed", e);
          }
      }

      if(!v) {
          showToast("Vendor profile not found. Please set up your store.", "error");
          return false;
      }

      const { customCategory, vendorId, ...dbProduct } = prod;

      // snake_case payload
      const productPayload = {
          vendor_id: v.vendorId, 
          title: dbProduct.title,
          description: dbProduct.description,
          price: dbProduct.price,
          currency: 'GHS',
          category: dbProduct.category,
          images: dbProduct.images,
          stock: dbProduct.stock,
          status: 'pending',
          location: dbProduct.location,
          contact_phone: dbProduct.contactPhone
      };

      const { error } = await supabase.from('products').insert(productPayload);

      if (error) {
          console.error("Supabase Insert Error:", error);
          showToast(`Failed to add product: ${error.message}`, "error");
          return false;
      }

      showToast("Product submitted for approval", "success"); 
      fetchData(); 
      return true;
  };

  const updateProduct = async (id: string, data: any) => {
      const { customCategory, vendorId, contactPhone, ...rest } = data;

      // Map to snake_case for update
      const updatePayload = {
          ...rest,
          contact_phone: contactPhone
      };

      const { error } = await supabase.from('products').update(updatePayload).eq('id', id);

      if (error) {
          showToast("Update failed", "error");
          console.error(error);
      } else {
          showToast("Product updated", "success");
          fetchData();
      }
  };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);

  const toggleFavorite = (pid: string) => {
      const isFav = favorites.includes(pid);
      if (isFav) {
          setFavorites(prev => prev.filter(i => i !== pid));
          showToast("Removed from Wishlist", "info");
      } else {
          setFavorites(prev => [...prev, pid]);
          showToast("Added to Wishlist ❤️", "success");
      }
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });

      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);

              const { error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, 
                  vendor_id: vid, 
                  items, 
                  total: subtotal+fee, 
                  delivery_fee: fee, 
                  status: 'placed', 
                  delivery_option: option 
              });

              if (error) {
                 throw error;
              }
          }
          showToast("Order Placed!", "success"); 
          clearCart(); 
          fetchData();
      } catch (e: any) {
          console.error("Order failed:", e);
          showToast(`Order failed: ${e.message}`, "error");
      }
  };

  const updateOrderStatus = async (oid: string, status: string) => { await supabase.from('orders').update({status}).eq('id', oid); fetchData(); };

  const assignDelivery = async (oid: string) => { 
      if(currentUser) await supabase.from('orders').update({
          delivery_person_id: currentUser.id, 
          status: 'assigned'
      }).eq('id', oid); 
      fetchData(); 
  };

  // =========================================================
  // ADMIN ACTIONS - STRICT SNAKE_CASE & VERIFICATION
  // =========================================================

  const banUser = async (uid: string, s: boolean) => { 
      try {
          const { data, error } = await supabase.from('profiles').update({ is_banned: s }).eq('id', uid).select();

          if (error) throw error;
          if (!data || data.length === 0) {
              throw new Error("Permission denied or user not found. Check if you have Admin rights.");
          }

          showToast(s ? "User Banned" : "User Unbanned", "success");
          fetchData(); 
      } catch (e: any) {
          console.error("Ban failed", e);
          showToast("Action failed: " + e.message, "error");
      }
  };

  const deleteUser = async (uid: string) => { 
      try {
          const { data, error } = await supabase.from('profiles').delete().eq('id', uid).select();
          if (error) throw error;
          if (!data || data.length === 0) {
              throw new Error("Permission denied or user not found.");
          }
          showToast("User deleted", "success");
          fetchData(); 
      } catch (e: any) {
           showToast("Delete failed: " + e.message, "error");
      }
  };

  const approveVendor = async (vid: string, s: boolean) => { 
      showToast(s ? "Approving vendor..." : "Suspending vendor...", "info");

      try {
          // Update using the unique vendor_id
          const { data, error } = await supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid).select();

          if (error) throw error;
          if (!data || data.length === 0) {
               throw new Error("Permission denied or vendor not found.");
          }

          await fetchData();
          showToast(s ? "Vendor Approved" : "Vendor Suspended", "success");
      } catch (err: any) {
          console.error("Approval Error Details:", err);
          showToast(`Failed: ${err.message}`, "error");
      }
  };

  const approveDeliveryPerson = async (id: string, uid: string, status: string) => { 
      try {
          const { data, error } = await supabase.from('delivery_persons').update({status}).eq('id', id).select();
          if (error) throw error;
          if (!data || data.length === 0) throw new Error("Permission denied or rider not found.");

          if(status === 'approved') {
               const { data: userData } = await supabase.from('profiles').select('roles').eq('id', uid).single();
               if(userData) {
                   const newRoles = [...(userData.roles || []), 'deliveryPerson'];
                   const uniqueRoles = Array.from(new Set(newRoles));
                   await supabase.from('profiles').update({roles: uniqueRoles}).eq('id', uid);
               }
          }
          showToast("Rider updated", "success");
          fetchData(); 
      } catch (e: any) {
          console.error("Delivery approval failed", e);
          showToast("Action failed: " + e.message, "error");
      }
  };

  const updateProductStatus = async (id: string, status: string) => { 
      try {
        const { data, error } = await supabase.from('products').update({status}).eq('id', id).select(); 
        if (error) throw error;
        if (!data || data.length === 0) throw new Error("Permission denied or product not found.");

        showToast(`Product ${status}`, "success"); 
        fetchData(); 
      } catch(e: any) {
        showToast("Update failed: " + e.message, "error");
      }
  };

  const deleteProduct = async (id: string) => { 
      try {
        const { data, error } = await supabase.from('products').delete().eq('id', id).select(); 
        if (error) throw error;
        if (!data || data.length === 0) throw new Error("Permission denied or product not found.");

        showToast("Product deleted", "success"); 
        fetchData(); 
      } catch(e: any) {
        showToast("Delete failed: " + e.message, "error");
      }
  };

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, deliveryPersons, users, isLoading, isDataLoading, cart, favorites, toast,
        login, signup, logout, resetPassword, updatePassword, switchRole,
        uploadFile, registerVendor, registerDeliveryPerson, refreshData: fetchData,
        addProduct, updateProduct, updateProductStatus, deleteProduct,
        addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
        banUser, deleteUser, approveVendor, approveDeliveryPerson,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Product, Vendor, Order, CartItem, DeliveryPerson, Role, OrderStatus } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { INITIAL_LOCATION_CACHE } from './constants';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  deliveryPersons: DeliveryPerson[];
  users: User[];
  isLoading: boolean;
  isDataLoading: boolean;
  favorites: string[];
  toast: ToastMessage | null;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role) => Promise<{success: boolean, error?: string}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerDeliveryPerson: (data: Partial<DeliveryPerson>) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveDeliveryPerson: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// Helper to safely write to localStorage without crashing app if full
const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [deliveryPersons, setDeliveryPersons] = useState<DeliveryPerson[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // Keep small items in Storage
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // State Persistence (Only for small items)
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // CRITICAL FIX: CLEAN UP BLOATED STORAGE ON MOUNT
  useEffect(() => {
      try {
          localStorage.removeItem('lynqed_products');
          localStorage.removeItem('lynqed_vendors');
          localStorage.removeItem('lynqed_orders');
          localStorage.removeItem('lynqed_drivers');
      } catch(e) {
          console.error("Cleanup failed", e);
      }
  }, []);

  // Refs to hold latest state for event listeners to avoid dependency loops
  const vendorsRef = useRef(vendors);
  const currentUserRef = useRef(currentUser);
  const currentRoleRef = useRef(currentRole);

  useEffect(() => { vendorsRef.current = vendors; }, [vendors]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);
  useEffect(() => { currentRoleRef.current = currentRole; }, [currentRole]);

  // Audio Notification Helper
  const playNotificationSound = () => {
      try {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          if (!AudioContext) return;

          const ctx = new AudioContext();
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();

          osc.connect(gain);
          gain.connect(ctx.destination);

          osc.type = 'sine';
          osc.frequency.setValueAtTime(500, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1000, ctx.currentTime + 0.1);

          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);

          osc.start();
          osc.stop(ctx.currentTime + 0.5);
      } catch (e) {
          console.error("Audio play failed", e);
      }
  };

  // --- INITIALIZATION LOGIC ---
  useEffect(() => {
    let mounted = true;

    const initAuth = async () => {
        try {
            // 1. Check active session
            const { data: { session } } = await supabase.auth.getSession();

            if (mounted) {
                if (session?.user) {
                    await fetchUserProfile(session.user.id);
                } else {
                    setCurrentUser(null);
                    setCurrentRole('guest');
                }

                // 2. Fetch Data immediately if authenticated or just basics
                fetchData();
            }
        } catch (e) {
            console.error("Auth Init Error", e);
        } finally {
            if (mounted) setIsLoading(false);
        }
    };

    initAuth();

    // 3. Auth Listener for changes
    const { data: authListener } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (event === 'SIGNED_IN' || event === 'TOKEN_REFRESHED') {
            if (session?.user) {
                // Do not set isLoading true here to avoid flashing, just update
                await fetchUserProfile(session.user.id);
            }
        }
        if (event === 'SIGNED_OUT') {
             setCurrentUser(null);
             setCurrentRole('guest');
             localStorage.removeItem('lynqed_role');
             setCart([]);
        }
    });

    // 4. Data Subscriptions
    const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();
    const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
          fetchData();
          if (payload.eventType === 'INSERT' && currentRoleRef.current === 'vendor') {
              const newOrder = payload.new as any; 
              const myVendorId = vendorsRef.current.find(v => v.userId === currentUserRef.current?.id)?.vendorId;
              if (myVendorId && newOrder.vendor_id === myVendorId) {
                  playNotificationSound();
                  setToast({ message: "🔔 New Order Received!", type: "info" });
              }
          }
      }).subscribe();

    return () => {
        mounted = false;
        authListener.subscription.unsubscribe();
        supabase.removeChannel(productSub);
        supabase.removeChannel(orderSub);
    };
  }, []); 

  const fetchUserProfile = async (userId: string) => {
      try {
          const persistedRole = localStorage.getItem('lynqed_role') as Role;

          const { data } = await supabase.from('profiles').select('*').eq('id', userId).single();

          if (data) {
              const isBanned = data.is_banned ?? false;
              if (isBanned) {
                  await logout();
                  alert("Account Suspended");
                  return null;
              }
              const user: User = { 
                  id: data.id,
                  name: data.name,
                  email: data.email,
                  roles: data.roles || ['buyer'],
                  avatarUrl: data.avatar_url,
                  defaultLocation: data.default_location,
                  isBanned: isBanned
              };
              setCurrentUser(user);

              // FORCE ADMIN ROLE if user is admin, ignoring local storage drift
              if (user.roles.includes('admin')) {
                  setCurrentRole('admin');
                  safeSetItem('lynqed_role', 'admin');
              } 
              // Otherwise try to respect last used role if valid
              else if (persistedRole && user.roles.includes(persistedRole)) {
                  setCurrentRole(persistedRole);
              } 
              // Fallback based on available roles
              else {
                  if (user.roles.includes('vendor')) setCurrentRole('vendor');
                  else if (user.roles.includes('deliveryPerson')) setCurrentRole('deliveryPerson');
                  else setCurrentRole('buyer');
              }
              return user;
          }
      } catch (e) {
          console.error("Profile fetch error", e);
      }
      return null;
  };

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, orderBy?: string) => {
             try {
                let query = supabase.from(table).select('*');
                if (orderBy) query = query.order(orderBy, { ascending: false });
                const { data, error } = await query;
                return error ? null : data;
             } catch { return null; }
          };

          const [pData, vData, oData, dData] = await Promise.all([
              fetchSafely('products', 'created_at'),
              fetchSafely('vendors'),
              fetchSafely('orders', 'created_at'),
              fetchSafely('delivery_persons')
          ]);

          if (pData) setProducts(pData.map((p: any) => ({
              ...p,
              vendorId: p.vendor_id,
              contactPhone: p.contact_phone,
          })) as Product[]);

          if (vData) {
              setVendors(vData.map((v: any) => ({
                  ...v,
                  id: v.id, 
                  vendorId: v.vendor_id, 
                  userId: v.user_id,
                  storeName: v.store_name,
                  storeDescription: v.store_description,
                  storeAvatarUrl: v.store_avatar_url,
                  contactPhone: v.contact_phone,
                  isApproved: v.is_approved
              })) as Vendor[]);
          }

          if (oData) {
              setOrders(oData.map((o: any) => ({
                  ...o, 
                  vendorId: o.vendor_id,
                  buyerId: o.buyer_id,
                  deliveryPersonId: o.delivery_person_id,
                  deliveryFee: o.delivery_fee,
                  deliveryOption: o.delivery_option,
                  locationCoordinates: o.location_coordinates,
                  createdAt: o.created_at,
                  items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items
              })) as Order[]);
          }
          if (dData) setDeliveryPersons(dData.map((d: any) => ({
             ...d,
             userId: d.user_id,
             fullName: d.full_name,
             vehicleType: d.vehicle_type,
             totalDeliveries: d.total_deliveries,
          })) as DeliveryPerson[]);

          // Check role from storage if state isn't ready yet or direct check
          const r = localStorage.getItem('lynqed_role');
          if (r === 'admin') {
              const uData = await fetchSafely('profiles');
              if (uData) setUsers(uData.map((u:any) => ({
                  id: u.id,
                  name: u.name,
                  email: u.email,
                  avatarUrl: u.avatar_url,
                  roles: u.roles,
                  defaultLocation: u.default_location,
                  isBanned: u.is_banned
              })) as any);
          }
      } catch (e) { console.error(e); } 
      finally { setIsDataLoading(false); }
  };

  // Auth Functions
  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });

      if (error) {
          try {
              const { data: userProfile } = await supabase.from('profiles').select('id').eq('email', email).maybeSingle();
              if (!userProfile) {
                  return { success: false, error: "Account does not exist. Please register." };
              }
          } catch (e) {}
          return { success: false, error: "Invalid password. Please try again." };
      }

      if (data.user) {
          const user = await fetchUserProfile(data.user.id);
          fetchData();

          let role: Role = 'buyer';
          if (user) {
              // Re-evaluate role logic here or just rely on state updated by fetchUserProfile
              // We return the state logic to be consistent with fetchUserProfile
              if (user.roles.includes('admin')) role = 'admin';
              else if (user.roles.includes('vendor')) role = 'vendor';
              else if (user.roles.includes('deliveryPerson')) role = 'deliveryPerson';
          }
          return { success: true, role }; 
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName, roles: [role] } } });
      if (error) return { success: false, error: error.message };
      if (data.user) {
           await supabase.from('profiles').insert({ 
               id: data.user.id, 
               email, 
               name: fullName, 
               roles: [role],
               is_banned: false 
           });
           await login(email, password);
           return { success: true };
      }
      return { success: false };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  const resetPassword = async (email: string) => { return { success: true }; };
  const updatePassword = async (pass: string) => { return { success: true }; };
  const switchRole = (role: Role) => { if(currentUser?.roles.includes(role)) setCurrentRole(role); };

  // Utils
  const showToast = (message: string, type: 'success'|'error'|'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => (await Notification.requestPermission()) === 'granted';

  // --- STORAGE UPLOAD HELPER ---
  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileExt = file.name.split('.').pop();
          const fileName = `${Math.random().toString(36).substring(2, 15)}_${Date.now()}.${fileExt}`;
          const filePath = `${folder}/${fileName}`;

          const { error: uploadError } = await supabase.storage
              .from('lynqed-assets')
              .upload(filePath, file);

          if (uploadError) {
              console.error('Upload error:', uploadError);
              showToast(`Upload failed: ${uploadError.message}`, 'error');
              return null;
          }

          const { data } = supabase.storage.from('lynqed-assets').getPublicUrl(filePath);
          return data.publicUrl;
      } catch (error: any) {
          console.error('Storage error:', error);
          showToast('Image upload failed', 'error');
          return null;
      }
  };

  // Specific Actions
  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      try {
          const { data: existing } = await supabase.from('vendors').select('id').eq('user_id', currentUser.id).maybeSingle();
          let error;
          if (existing) {
               const { error: upError } = await supabase.from('vendors').update({
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl
               }).eq('user_id', currentUser.id);
               error = upError;
          } else {
               const { error: inError } = await supabase.from('vendors').insert({ 
                   vendor_id: `v-${Date.now()}`, 
                   user_id: currentUser.id, 
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl,
                   is_approved: false, 
                   rating: 5.0 
               });
               error = inError;
          }
          if (error) {
              showToast(`Registration failed: ${error.message || 'Database error'}`, "error");
              return { success: false };
          } 
          showToast("Store profile saved successfully", "success"); 
          await fetchData();
          return { success: true };
      } catch (e: any) {
          showToast(`Unexpected error: ${e.message || e}`, "error");
          return { success: false };
      }
  };

  const registerDeliveryPerson = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };
      const { error } = await supabase.from('delivery_persons').insert({ 
          user_id: currentUser.id, 
          full_name: data.fullName,
          vehicle_type: data.vehicleType,
          status: 'pending' 
      });
      if (error) {
          showToast(`Application failed: ${error.message}`, "error");
          return { success: false };
      }
      showToast("Rider application submitted", "success"); 
      fetchData();
      return { success: true };
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) { showToast("You must be logged in.", "error"); return false; }
      let v = vendors.find(v => v.userId === currentUser.id);
      if (!v) {
          try {
             const { data } = await supabase.from('vendors').select('*').eq('user_id', currentUser.id).maybeSingle();
             if(data) {
                 v = { ...data, vendorId: data.vendor_id, userId: data.user_id, storeName: data.store_name || 'My Store', storeDescription: '', location: '', isApproved: data.is_approved, rating: 5 };
             }
          } catch(e) {}
      }
      if(!v) { showToast("Vendor profile not found. Please set up your store.", "error"); return false; }

      const { customCategory, vendorId, ...dbProduct } = prod;
      const productPayload = {
          vendor_id: v.vendorId, 
          title: dbProduct.title,
          description: dbProduct.description,
          price: dbProduct.price,
          currency: 'GHS',
          category: dbProduct.category,
          images: dbProduct.images,
          stock: dbProduct.stock,
          status: 'pending',
          location: dbProduct.location,
          contact_phone: dbProduct.contactPhone
      };
      const { error } = await supabase.from('products').insert(productPayload);
      if (error) { showToast(`Failed to add product: ${error.message}`, "error"); return false; }
      showToast("Product submitted for approval", "success"); 
      fetchData(); 
      return true;
  };

  const updateProduct = async (id: string, data: any) => {
      const { customCategory, vendorId, contactPhone, ...rest } = data;
      const updatePayload = { ...rest, contact_phone: contactPhone };
      const { error } = await supabase.from('products').update(updatePayload).eq('id', id);
      if (error) { showToast("Update failed", "error"); } 
      else { showToast("Product updated", "success"); fetchData(); }
  };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);
  const toggleFavorite = (pid: string) => {
      const isFav = favorites.includes(pid);
      if (isFav) { setFavorites(prev => prev.filter(i => i !== pid)); showToast("Removed from Wishlist", "info"); } 
      else { setFavorites(prev => [...prev, pid]); showToast("Added to Wishlist ❤️", "success"); }
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });
      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const { error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, 
                  vendor_id: vid, 
                  items, 
                  total: subtotal+fee, 
                  delivery_fee: fee, 
                  status: 'placed', 
                  delivery_option: option 
              });
              if (error) throw error;
          }
          showToast("Order Placed!", "success"); clearCart(); fetchData();
      } catch (e: any) { showToast(`Order failed: ${e.message}`, "error"); }
  };

  const updateOrderStatus = async (oid: string, status: string) => { await supabase.from('orders').update({status}).eq('id', oid); fetchData(); };
  const assignDelivery = async (oid: string) => { if(currentUser) await supabase.from('orders').update({ delivery_person_id: currentUser.id, status: 'assigned' }).eq('id', oid); fetchData(); };

  const banUser = async (uid: string, s: boolean) => { 
      try {
          const { data, error } = await supabase.from('profiles').update({ is_banned: s }).eq('id', uid).select();
          if (error) throw error;
          if (!data || data.length === 0) throw new Error("Permission denied or user not found.");
          showToast(s ? "User Banned" : "User Unbanned", "success"); fetchData(); 
      } catch (e: any) { showToast("Action failed: " + e.message, "error"); }
  };
  const deleteUser = async (uid: string) => { 
      try {
          const { data, error } = await supabase.from('profiles').delete().eq('id', uid).select();
          if (error) throw error;
          if (!data || data.length === 0) throw new Error("Permission denied.");
          showToast("User deleted", "success"); fetchData(); 
      } catch (e: any) { showToast("Delete failed: " + e.message, "error"); }
  };
  const approveVendor = async (vid: string, s: boolean) => { 
      showToast(s ? "Approving vendor..." : "Suspending vendor...", "info");
      try {
          const { data, error } = await supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid).select();
          if (error) throw error;
          if (!data || data.length === 0) throw new Error("Permission denied.");
          await fetchData(); showToast(s ? "Vendor Approved" : "Vendor Suspended", "success");
      } catch (err: any) { showToast(`Failed: ${err.message}`, "error"); }
  };
  const approveDeliveryPerson = async (id: string, uid: string, status: string) => { 
      try {
          const { data, error } = await supabase.from('delivery_persons').update({status}).eq('id', id).select();
          if (error) throw error;
          if (!data || data.length === 0) throw new Error("Permission denied.");
          if(status === 'approved') {
               const { data: userData } = await supabase.from('profiles').select('roles').eq('id', uid).single();
               if(userData) {
                   const newRoles = [...(userData.roles || []), 'deliveryPerson'];
                   const uniqueRoles = Array.from(new Set(newRoles));
                   await supabase.from('profiles').update({roles: uniqueRoles}).eq('id', uid);
               }
          }
          showToast("Rider updated", "success"); fetchData(); 
      } catch (e: any) { showToast("Action failed: " + e.message, "error"); }
  };
  const updateProductStatus = async (id: string, status: string) => { 
      try {
        const { data, error } = await supabase.from('products').update({status}).eq('id', id).select(); 
        if (error) throw error;
        if (!data || data.length === 0) throw new Error("Permission denied.");
        showToast(`Product ${status}`, "success"); fetchData(); 
      } catch(e: any) { showToast("Update failed: " + e.message, "error"); }
  };
  const deleteProduct = async (id: string) => { 
      try {
        const { data, error } = await supabase.from('products').delete().eq('id', id).select(); 
        if (error) throw error;
        if (!data || data.length === 0) throw new Error("Permission denied.");
        showToast("Product deleted", "success"); fetchData(); 
      } catch(e: any) { showToast("Delete failed: " + e.message, "error"); }
  };

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, deliveryPersons, users, isLoading, isDataLoading, cart, favorites, toast,
        login, signup, logout, resetPassword, updatePassword, switchRole,
        uploadFile, registerVendor, registerDeliveryPerson, refreshData: fetchData,
        addProduct, updateProduct, updateProductStatus, deleteProduct,
        addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
        banUser, deleteUser, approveVendor, approveDeliveryPerson,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Product, Vendor, Order, CartItem, DeliveryPerson, Role, OrderStatus } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { INITIAL_LOCATION_CACHE } from './constants';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  deliveryPersons: DeliveryPerson[];
  users: User[];
  isLoading: boolean;
  isDataLoading: boolean;
  favorites: string[];
  toast: ToastMessage | null;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role) => Promise<{success: boolean, error?: string}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerDeliveryPerson: (data: Partial<DeliveryPerson>) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveDeliveryPerson: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// Helper to safely write to localStorage without crashing app if full
const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [deliveryPersons, setDeliveryPersons] = useState<DeliveryPerson[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // Keep small items in Storage
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // State Persistence (Only for small items)
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // CRITICAL FIX: CLEAN UP BLOATED STORAGE ON MOUNT
  useEffect(() => {
      try {
          localStorage.removeItem('lynqed_products');
          localStorage.removeItem('lynqed_vendors');
          localStorage.removeItem('lynqed_orders');
          localStorage.removeItem('lynqed_drivers');
      } catch(e) {
          console.error("Cleanup failed", e);
      }
  }, []);

  // Refs to hold latest state for event listeners to avoid dependency loops
  const vendorsRef = useRef(vendors);
  const currentUserRef = useRef(currentUser);
  const currentRoleRef = useRef(currentRole);

  useEffect(() => { vendorsRef.current = vendors; }, [vendors]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);
  useEffect(() => { currentRoleRef.current = currentRole; }, [currentRole]);

  // Audio Notification Helper
  const playNotificationSound = () => {
      try {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          if (!AudioContext) return;

          const ctx = new AudioContext();
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();

          osc.connect(gain);
          gain.connect(ctx.destination);

          osc.type = 'sine';
          osc.frequency.setValueAtTime(500, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1000, ctx.currentTime + 0.1);

          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);

          osc.start();
          osc.stop(ctx.currentTime + 0.5);
      } catch (e) {
          console.error("Audio play failed", e);
      }
  };

  // --- INITIALIZATION LOGIC ---
  useEffect(() => {
    let mounted = true;

    const initAuth = async () => {
        try {
            // 1. Check active session
            const { data: { session } } = await supabase.auth.getSession();

            if (mounted) {
                if (session?.user) {
                    await fetchUserProfile(session.user.id);
                } else {
                    setCurrentUser(null);
                    setCurrentRole('guest');
                }

                // 2. Fetch Data immediately if authenticated or just basics
                fetchData();
            }
        } catch (e) {
            console.error("Auth Init Error", e);
        } finally {
            if (mounted) setIsLoading(false);
        }
    };

    initAuth();

    // 3. Auth Listener for changes
    const { data: authListener } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (event === 'SIGNED_IN' || event === 'TOKEN_REFRESHED') {
            if (session?.user) {
                // Do not set isLoading true here to avoid flashing, just update
                await fetchUserProfile(session.user.id);
            }
        }
        if (event === 'SIGNED_OUT') {
             setCurrentUser(null);
             setCurrentRole('guest');
             localStorage.removeItem('lynqed_role');
             setCart([]);
        }
    });

    // 4. Data Subscriptions
    const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();
    const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
          fetchData();
          if (payload.eventType === 'INSERT' && currentRoleRef.current === 'vendor') {
              const newOrder = payload.new as any; 
              const myVendorId = vendorsRef.current.find(v => v.userId === currentUserRef.current?.id)?.vendorId;
              if (myVendorId && newOrder.vendor_id === myVendorId) {
                  playNotificationSound();
                  setToast({ message: "🔔 New Order Received!", type: "info" });
              }
          }
      }).subscribe();

    return () => {
        mounted = false;
        authListener.subscription.unsubscribe();
        supabase.removeChannel(productSub);
        supabase.removeChannel(orderSub);
    };
  }, []); 

  const fetchUserProfile = async (userId: string) => {
      try {
          const persistedRole = localStorage.getItem('lynqed_role') as Role;

          const { data } = await supabase.from('profiles').select('*').eq('id', userId).single();

          if (data) {
              const isBanned = data.is_banned ?? false;
              if (isBanned) {
                  await logout();
                  alert("Account Suspended");
                  return null;
              }
              const user: User = { 
                  id: data.id,
                  name: data.name,
                  email: data.email,
                  roles: data.roles || ['buyer'],
                  avatarUrl: data.avatar_url,
                  defaultLocation: data.default_location,
                  isBanned: isBanned
              };
              setCurrentUser(user);

              // FORCE ADMIN ROLE if user is admin, ignoring local storage drift
              if (user.roles.includes('admin')) {
                  setCurrentRole('admin');
                  safeSetItem('lynqed_role', 'admin');
              } 
              // Otherwise try to respect last used role if valid
              else if (persistedRole && user.roles.includes(persistedRole)) {
                  setCurrentRole(persistedRole);
              } 
              // Fallback based on available roles
              else {
                  if (user.roles.includes('vendor')) setCurrentRole('vendor');
                  else if (user.roles.includes('deliveryPerson')) setCurrentRole('deliveryPerson');
                  else setCurrentRole('buyer');
              }
              return user;
          }
      } catch (e) {
          console.error("Profile fetch error", e);
      }
      return null;
  };

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, orderBy?: string) => {
             try {
                let query = supabase.from(table).select('*');
                if (orderBy) query = query.order(orderBy, { ascending: false });
                const { data, error } = await query;
                return error ? null : data;
             } catch { return null; }
          };

          const [pData, vData, oData, dData] = await Promise.all([
              fetchSafely('products', 'created_at'),
              fetchSafely('vendors'),
              fetchSafely('orders', 'created_at'),
              fetchSafely('delivery_persons')
          ]);

          if (pData) setProducts(pData.map((p: any) => ({
              ...p,
              vendorId: p.vendor_id,
              contactPhone: p.contact_phone,
          })) as Product[]);

          if (vData) {
              setVendors(vData.map((v: any) => ({
                  ...v,
                  id: v.id, 
                  vendorId: v.vendor_id, 
                  userId: v.user_id,
                  storeName: v.store_name,
                  storeDescription: v.store_description,
                  storeAvatarUrl: v.store_avatar_url,
                  contactPhone: v.contact_phone,
                  isApproved: v.is_approved
              })) as Vendor[]);
          }

          if (oData) {
              setOrders(oData.map((o: any) => ({
                  ...o, 
                  vendorId: o.vendor_id,
                  buyerId: o.buyer_id,
                  deliveryPersonId: o.delivery_person_id,
                  deliveryFee: o.delivery_fee,
                  deliveryOption: o.delivery_option,
                  locationCoordinates: o.location_coordinates,
                  createdAt: o.created_at,
                  items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items
              })) as Order[]);
          }
          if (dData) setDeliveryPersons(dData.map((d: any) => ({
             ...d,
             userId: d.user_id,
             fullName: d.full_name,
             vehicleType: d.vehicle_type,
             totalDeliveries: d.total_deliveries,
          })) as DeliveryPerson[]);

          // Check role from storage if state isn't ready yet or direct check
          const r = localStorage.getItem('lynqed_role');
          if (r === 'admin') {
              const uData = await fetchSafely('profiles');
              if (uData) setUsers(uData.map((u:any) => ({
                  id: u.id,
                  name: u.name,
                  email: u.email,
                  avatarUrl: u.avatar_url,
                  roles: u.roles,
                  defaultLocation: u.default_location,
                  isBanned: u.is_banned
              })) as any);
          }
      } catch (e) { console.error(e); } 
      finally { setIsDataLoading(false); }
  };

  // Auth Functions
  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });

      if (error) {
          try {
              const { data: userProfile } = await supabase.from('profiles').select('id').eq('email', email).maybeSingle();
              if (!userProfile) {
                  return { success: false, error: "Account does not exist. Please register." };
              }
          } catch (e) {}
          return { success: false, error: "Invalid password. Please try again." };
      }

      if (data.user) {
          const user = await fetchUserProfile(data.user.id);
          fetchData();

          let role: Role = 'buyer';
          if (user) {
              // Re-evaluate role logic here or just rely on state updated by fetchUserProfile
              // We return the state logic to be consistent with fetchUserProfile
              if (user.roles.includes('admin')) role = 'admin';
              else if (user.roles.includes('vendor')) role = 'vendor';
              else if (user.roles.includes('deliveryPerson')) role = 'deliveryPerson';
          }
          return { success: true, role }; 
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role) => {
      // 1. Authenticate with Supabase
      const { data, error } = await supabase.auth.signUp({ 
          email, 
          password, 
          options: { data: { full_name: fullName, roles: [role] } } 
      });

      if (error) return { success: false, error: error.message };

      if (data.user) {
           // 2. Create Profile Record
           const { error: profileError } = await supabase.from('profiles').insert({ 
               id: data.user.id, 
               email, 
               name: fullName, 
               roles: [role],
               is_banned: false 
           });

           if (profileError) {
               console.error("Profile creation failed:", profileError);
               return { success: false, error: "Failed to initialize profile. Please contact support." };
           }

           // 3. Optimized Login Flow
           // If session exists (email confirmation disabled or auto-login worked), skip redundant signInWithPassword
           if (data.session) {
               await fetchUserProfile(data.user.id);
               fetchData(); // Load background data
               return { success: true };
           }

           // Fallback if session wasn't returned immediately (rare)
           return await login(email, password);
      }
      return { success: false };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  const resetPassword = async (email: string) => { return { success: true }; };
  const updatePassword = async (pass: string) => { return { success: true }; };
  const switchRole = (role: Role) => { if(currentUser?.roles.includes(role)) setCurrentRole(role); };

  // Utils
  const showToast = (message: string, type: 'success'|'error'|'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => (await Notification.requestPermission()) === 'granted';

  // --- STORAGE UPLOAD HELPER ---
  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileExt = file.name.split('.').pop();
          const fileName = `${Math.random().toString(36).substring(2, 15)}_${Date.now()}.${fileExt}`;
          const filePath = `${folder}/${fileName}`;

          const { error: uploadError } = await supabase.storage
              .from('lynqed-assets')
              .upload(filePath, file);

          if (uploadError) {
              console.error('Upload error:', uploadError);
              showToast(`Upload failed: ${uploadError.message}`, 'error');
              return null;
          }

          const { data } = supabase.storage.from('lynqed-assets').getPublicUrl(filePath);
          return data.publicUrl;
      } catch (error: any) {
          console.error('Storage error:', error);
          showToast('Image upload failed', 'error');
          return null;
      }
  };

  // Specific Actions
  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      try {
          const { data: existing } = await supabase.from('vendors').select('id').eq('user_id', currentUser.id).maybeSingle();
          let error;
          if (existing) {
               const { error: upError } = await supabase.from('vendors').update({
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl
               }).eq('user_id', currentUser.id);
               error = upError;
          } else {
               const { error: inError } = await supabase.from('vendors').insert({ 
                   vendor_id: `v-${Date.now()}`, 
                   user_id: currentUser.id, 
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl,
                   is_approved: false, 
                   rating: 5.0 
               });
               error = inError;
          }
          if (error) {
              showToast(`Registration failed: ${error.message || 'Database error'}`, "error");
              return { success: false };
          } 
          showToast("Store profile saved successfully", "success"); 
          await fetchData();
          return { success: true };
      } catch (e: any) {
          showToast(`Unexpected error: ${e.message || e}`, "error");
          return { success: false };
      }
  };

  const registerDeliveryPerson = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };
      const { error } = await supabase.from('delivery_persons').insert({ 
          user_id: currentUser.id, 
          full_name: data.fullName,
          vehicle_type: data.vehicleType,
          status: 'pending' 
      });
      if (error) {
          showToast(`Application failed: ${error.message}`, "error");
          return { success: false };
      }
      showToast("Rider application submitted", "success"); 
      fetchData();
      return { success: true };
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) { showToast("You must be logged in.", "error"); return false; }
      let v = vendors.find(v => v.userId === currentUser.id);
      if (!v) {
          try {
             const { data } = await supabase.from('vendors').select('*').eq('user_id', currentUser.id).maybeSingle();
             if(data) {
                 v = { ...data, vendorId: data.vendor_id, userId: data.user_id, storeName: data.store_name || 'My Store', storeDescription: '', location: '', isApproved: data.is_approved, rating: 5 };
             }
          } catch(e) {}
      }
      if(!v) { showToast("Vendor profile not found. Please set up your store.", "error"); return false; }

      const { customCategory, vendorId, ...dbProduct } = prod;
      const productPayload = {
          vendor_id: v.vendorId, 
          title: dbProduct.title,
          description: dbProduct.description,
          price: dbProduct.price,
          currency: 'GHS',
          category: dbProduct.category,
          images: dbProduct.images,
          stock: dbProduct.stock,
          status: 'pending',
          location: dbProduct.location,
          contact_phone: dbProduct.contactPhone
      };
      const { error } = await supabase.from('products').insert(productPayload);
      if (error) { showToast(`Failed to add product: ${error.message}`, "error"); return false; }
      showToast("Product submitted for approval", "success"); 
      fetchData(); 
      return true;
  };

  const updateProduct = async (id: string, data: any) => {
      const { customCategory, vendorId, contactPhone, ...rest } = data;
      const updatePayload = { ...rest, contact_phone: contactPhone };
      const { error } = await supabase.from('products').update(updatePayload).eq('id', id);
      if (error) { showToast("Update failed", "error"); } 
      else { showToast("Product updated", "success"); fetchData(); }
  };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);
  const toggleFavorite = (pid: string) => {
      const isFav = favorites.includes(pid);
      if (isFav) { setFavorites(prev => prev.filter(i => i !== pid)); showToast("Removed from Wishlist", "info"); } 
      else { setFavorites(prev => [...prev, pid]); showToast("Added to Wishlist ❤️", "success"); }
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });
      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const { error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, 
                  vendor_id: vid, 
                  items, 
                  total: subtotal+fee, 
                  delivery_fee: fee, 
                  status: 'placed', 
                  delivery_option: option 
              });
              if (error) throw error;
          }
          showToast("Order Placed!", "success"); clearCart(); fetchData();
      } catch (e: any) { showToast(`Order failed: ${e.message}`, "error"); }
  };

  const updateOrderStatus = async (oid: string, status: string) => { await supabase.from('orders').update({status}).eq('id', oid); fetchData(); };
  const assignDelivery = async (oid: string) => { if(currentUser) await supabase.from('orders').update({ delivery_person_id: currentUser.id, status: 'assigned' }).eq('id', oid); fetchData(); };

  const banUser = async (uid: string, s: boolean) => { 
      try {
          const { data, error } = await supabase.from('profiles').update({ is_banned: s }).eq('id', uid).select();
          if (error) throw error;
          if (!data || data.length === 0) throw new Error("Permission denied or user not found.");
          showToast(s ? "User Banned" : "User Unbanned", "success"); fetchData(); 
      } catch (e: any) { showToast("Action failed: " + e.message, "error"); }
  };
  const deleteUser = async (uid: string) => { 
      try {
          const { data, error } = await supabase.from('profiles').delete().eq('id', uid).select();
          if (error) throw error;
          if (!data || data.length === 0) throw new Error("Permission denied.");
          showToast("User deleted", "success"); fetchData(); 
      } catch (e: any) { showToast("Delete failed: " + e.message, "error"); }
  };
  const approveVendor = async (vid: string, s: boolean) => { 
      showToast(s ? "Approving vendor..." : "Suspending vendor...", "info");
      try {
          const { data, error } = await supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid).select();
          if (error) throw error;
          if (!data || data.length === 0) throw new Error("Permission denied.");
          await fetchData(); showToast(s ? "Vendor Approved" : "Vendor Suspended", "success");
      } catch (err: any) { showToast(`Failed: ${err.message}`, "error"); }
  };
  const approveDeliveryPerson = async (id: string, uid: string, status: string) => { 
      try {
          const { data, error } = await supabase.from('delivery_persons').update({status}).eq('id', id).select();
          if (error) throw error;
          if (!data || data.length === 0) throw new Error("Permission denied.");
          if(status === 'approved') {
               const { data: userData } = await supabase.from('profiles').select('roles').eq('id', uid).single();
               if(userData) {
                   const newRoles = [...(userData.roles || []), 'deliveryPerson'];
                   const uniqueRoles = Array.from(new Set(newRoles));
                   await supabase.from('profiles').update({roles: uniqueRoles}).eq('id', uid);
               }
          }
          showToast("Rider updated", "success"); fetchData(); 
      } catch (e: any) { showToast("Action failed: " + e.message, "error"); }
  };
  const updateProductStatus = async (id: string, status: string) => { 
      try {
        const { data, error } = await supabase.from('products').update({status}).eq('id', id).select(); 
        if (error) throw error;
        if (!data || data.length === 0) throw new Error("Permission denied.");
        showToast(`Product ${status}`, "success"); fetchData(); 
      } catch(e: any) { showToast("Update failed: " + e.message, "error"); }
  };
  const deleteProduct = async (id: string) => { 
      try {
        const { data, error } = await supabase.from('products').delete().eq('id', id).select(); 
        if (error) throw error;
        if (!data || data.length === 0) throw new Error("Permission denied.");
        showToast("Product deleted", "success"); fetchData(); 
      } catch(e: any) { showToast("Delete failed: " + e.message, "error"); }
  };

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, deliveryPersons, users, isLoading, isDataLoading, cart, favorites, toast,
        login, signup, logout, resetPassword, updatePassword, switchRole,
        uploadFile, registerVendor, registerDeliveryPerson, refreshData: fetchData,
        addProduct, updateProduct, updateProductStatus, deleteProduct,
        addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
        banUser, deleteUser, approveVendor, approveDeliveryPerson,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { createContext, useContext, useState, useEffect, useRef } from 'react';
import { User, Product, Vendor, Order, CartItem, DeliveryPerson, Role, OrderStatus } from './types';
import { supabase } from './supabaseClient';
import { ToastMessage } from './components/UI';
import { INITIAL_LOCATION_CACHE } from './constants';

interface AppContextType {
  currentUser: User | null;
  currentRole: Role;
  products: Product[];
  vendors: Vendor[];
  orders: Order[];
  cart: CartItem[];
  deliveryPersons: DeliveryPerson[];
  users: User[];
  isLoading: boolean;
  isDataLoading: boolean;
  favorites: string[];
  toast: ToastMessage | null;

  login: (email: string, password: string) => Promise<{success: boolean, role?: Role, error?: string}>;
  signup: (email: string, password: string, fullName: string, role: Role) => Promise<{success: boolean, error?: string}>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<{success: boolean, error?: string}>;
  updatePassword: (password: string) => Promise<{success: boolean, error?: string}>;
  switchRole: (role: Role) => void;

  uploadFile: (file: File, folder: string) => Promise<string | null>;
  registerDeliveryPerson: (data: Partial<DeliveryPerson>) => Promise<{ success: boolean }>;
  registerVendor: (data: { storeName: string; storeDescription: string; location: string; contactPhone: string; storeAvatarUrl?: string }) => Promise<{ success: boolean }>;
  refreshData: () => Promise<void>;

  addProduct: (product: any) => Promise<boolean>;
  updateProduct: (id: string, data: Partial<Product>) => Promise<void>;
  updateProductStatus: (id: string, status: Product['status']) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;

  addToCart: (product: Product, quantity?: number) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  removeFromCart: (productId: string) => void;
  clearCart: () => void;
  placeOrder: (deliveryOption: 'delivery' | 'pickup', fee?: number) => Promise<void>;
  updateOrderStatus: (orderId: string, status: OrderStatus) => Promise<void>;
  assignDelivery: (orderId: string) => Promise<void>;
  toggleFavorite: (productId: string) => void;

  banUser: (userId: string, status: boolean) => Promise<void>;
  deleteUser: (userId: string) => Promise<void>;
  approveVendor: (vendorId: string, status: boolean) => Promise<void>;
  approveDeliveryPerson: (id: string, userId: string, status: 'approved' | 'rejected' | 'suspended') => Promise<void>;

  showToast: (message: string, type: 'success' | 'error' | 'info') => void;
  hideToast: () => void;
  requestNotificationPermission: () => Promise<boolean>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

// Helper to safely write to localStorage without crashing app if full
const safeSetItem = (key: string, value: string) => {
    try {
        localStorage.setItem(key, value);
    } catch (e) {
        console.warn(`LocalStorage quota exceeded. Failed to save ${key}.`);
    }
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [deliveryPersons, setDeliveryPersons] = useState<DeliveryPerson[]>([]);
  const [users, setUsers] = useState<User[]>([]);

  // Keep small items in Storage
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });

  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isDataLoading, setIsDataLoading] = useState<boolean>(true);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  // State Persistence (Only for small items)
  useEffect(() => { safeSetItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { safeSetItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') safeSetItem('lynqed_role', currentRole); }, [currentRole]);

  // CRITICAL FIX: CLEAN UP BLOATED STORAGE ON MOUNT
  useEffect(() => {
      try {
          localStorage.removeItem('lynqed_products');
          localStorage.removeItem('lynqed_vendors');
          localStorage.removeItem('lynqed_orders');
          localStorage.removeItem('lynqed_drivers');
      } catch(e) {
          console.error("Cleanup failed", e);
      }
  }, []);

  // Refs to hold latest state for event listeners to avoid dependency loops
  const vendorsRef = useRef(vendors);
  const currentUserRef = useRef(currentUser);
  const currentRoleRef = useRef(currentRole);

  useEffect(() => { vendorsRef.current = vendors; }, [vendors]);
  useEffect(() => { currentUserRef.current = currentUser; }, [currentUser]);
  useEffect(() => { currentRoleRef.current = currentRole; }, [currentRole]);

  // Audio Notification Helper
  const playNotificationSound = () => {
      try {
          const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
          if (!AudioContext) return;

          const ctx = new AudioContext();
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();

          osc.connect(gain);
          gain.connect(ctx.destination);

          osc.type = 'sine';
          osc.frequency.setValueAtTime(500, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1000, ctx.currentTime + 0.1);

          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);

          osc.start();
          osc.stop(ctx.currentTime + 0.5);
      } catch (e) {
          console.error("Audio play failed", e);
      }
  };

  // --- INITIALIZATION LOGIC ---
  useEffect(() => {
    let mounted = true;

    const initAuth = async () => {
        try {
            // 1. Check active session
            const { data: { session } } = await supabase.auth.getSession();

            if (mounted) {
                if (session?.user) {
                    await fetchUserProfile(session.user.id);
                } else {
                    setCurrentUser(null);
                    setCurrentRole('guest');
                }

                // 2. Fetch Data immediately if authenticated or just basics
                fetchData();
            }
        } catch (e) {
            console.error("Auth Init Error", e);
        } finally {
            if (mounted) setIsLoading(false);
        }
    };

    initAuth();

    // 3. Auth Listener for changes
    const { data: authListener } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (event === 'SIGNED_IN' || event === 'TOKEN_REFRESHED') {
            if (session?.user) {
                // Do not set isLoading true here to avoid flashing, just update
                await fetchUserProfile(session.user.id);
            }
        }
        if (event === 'SIGNED_OUT') {
             setCurrentUser(null);
             setCurrentRole('guest');
             localStorage.removeItem('lynqed_role');
             setCart([]);
        }
    });

    // 4. Data Subscriptions
    const productSub = supabase.channel('public:products').on('postgres_changes', { event: '*', schema: 'public', table: 'products' }, () => fetchData()).subscribe();
    const orderSub = supabase.channel('public:orders').on('postgres_changes', { event: '*', schema: 'public', table: 'orders' }, (payload) => {
          fetchData();
          if (payload.eventType === 'INSERT' && currentRoleRef.current === 'vendor') {
              const newOrder = payload.new as any; 
              const myVendorId = vendorsRef.current.find(v => v.userId === currentUserRef.current?.id)?.vendorId;
              if (myVendorId && newOrder.vendor_id === myVendorId) {
                  playNotificationSound();
                  setToast({ message: "🔔 New Order Received!", type: "info" });
              }
          }
      }).subscribe();

    return () => {
        mounted = false;
        authListener.subscription.unsubscribe();
        supabase.removeChannel(productSub);
        supabase.removeChannel(orderSub);
    };
  }, []); 

  const fetchUserProfile = async (userId: string) => {
      try {
          const persistedRole = localStorage.getItem('lynqed_role') as Role;

          const { data, error } = await supabase.from('profiles').select('*').eq('id', userId).single();

          if (error && error.code !== 'PGRST116') {
             console.warn("Profile fetch error:", error.message);
          }

          if (data) {
              const isBanned = data.is_banned ?? false;
              if (isBanned) {
                  await logout();
                  alert("Account Suspended");
                  return null;
              }
              const user: User = { 
                  id: data.id,
                  name: data.name,
                  email: data.email,
                  roles: data.roles || ['buyer'],
                  avatarUrl: data.avatar_url,
                  defaultLocation: data.default_location,
                  isBanned: isBanned
              };
              setCurrentUser(user);

              // FORCE ADMIN ROLE if user is admin, ignoring local storage drift
              if (user.roles.includes('admin')) {
                  setCurrentRole('admin');
                  safeSetItem('lynqed_role', 'admin');
              } 
              // Otherwise try to respect last used role if valid
              else if (persistedRole && user.roles.includes(persistedRole)) {
                  setCurrentRole(persistedRole);
              } 
              // Fallback based on available roles
              else {
                  if (user.roles.includes('vendor')) setCurrentRole('vendor');
                  else if (user.roles.includes('deliveryPerson')) setCurrentRole('deliveryPerson');
                  else setCurrentRole('buyer');
              }
              return user;
          }
      } catch (e) {
          console.error("Profile fetch exception", e);
      }
      return null;
  };

  const fetchData = async () => {
      try {
          const fetchSafely = async (table: string, orderBy?: string) => {
             try {
                let query = supabase.from(table).select('*');
                if (orderBy) query = query.order(orderBy, { ascending: false });
                const { data, error } = await query;
                return error ? null : data;
             } catch { return null; }
          };

          const [pData, vData, oData, dData] = await Promise.all([
              fetchSafely('products', 'created_at'),
              fetchSafely('vendors'),
              fetchSafely('orders', 'created_at'),
              fetchSafely('delivery_persons')
          ]);

          if (pData) setProducts(pData.map((p: any) => ({
              ...p,
              vendorId: p.vendor_id,
              contactPhone: p.contact_phone,
          })) as Product[]);

          if (vData) {
              setVendors(vData.map((v: any) => ({
                  ...v,
                  id: v.id, 
                  vendorId: v.vendor_id, 
                  userId: v.user_id,
                  storeName: v.store_name,
                  storeDescription: v.store_description,
                  storeAvatarUrl: v.store_avatar_url,
                  contactPhone: v.contact_phone,
                  isApproved: v.is_approved
              })) as Vendor[]);
          }

          if (oData) {
              setOrders(oData.map((o: any) => ({
                  ...o, 
                  vendorId: o.vendor_id,
                  buyerId: o.buyer_id,
                  deliveryPersonId: o.delivery_person_id,
                  deliveryFee: o.delivery_fee,
                  deliveryOption: o.delivery_option,
                  locationCoordinates: o.location_coordinates,
                  createdAt: o.created_at,
                  items: typeof o.items === 'string' ? JSON.parse(o.items) : o.items
              })) as Order[]);
          }
          if (dData) setDeliveryPersons(dData.map((d: any) => ({
             ...d,
             userId: d.user_id,
             fullName: d.full_name,
             vehicleType: d.vehicle_type,
             totalDeliveries: d.total_deliveries,
          })) as DeliveryPerson[]);

          // Check role from storage if state isn't ready yet or direct check
          const r = localStorage.getItem('lynqed_role');
          if (r === 'admin') {
              const uData = await fetchSafely('profiles');
              if (uData) setUsers(uData.map((u:any) => ({
                  id: u.id,
                  name: u.name,
                  email: u.email,
                  avatarUrl: u.avatar_url,
                  roles: u.roles,
                  defaultLocation: u.default_location,
                  isBanned: u.is_banned
              })) as any);
          }
      } catch (e) { console.error(e); } 
      finally { setIsDataLoading(false); }
  };

  // Auth Functions
  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });

      if (error) {
          // Improve UX: Check if user actually exists to give specific feedback
          try {
              // This might fail if RLS prevents lookup, but helpful if it works
              const { data: userProfile } = await supabase.from('profiles').select('id').eq('email', email).maybeSingle();
              if (userProfile === null && error.message.includes("Invalid login")) {
                   return { success: false, error: "Account does not exist. Please register." };
              }
          } catch (e) {}
          return { success: false, error: "Invalid credentials." };
      }

      if (data.user) {
          let user = await fetchUserProfile(data.user.id);

          // AUTO-HEAL: If auth worked but profile missing (race condition/deletion), create it
          if (!user) {
               console.log("Auth success but profile missing. Creating fallback profile...");
               const { error: insertError } = await supabase.from('profiles').insert({
                   id: data.user.id,
                   email: email,
                   name: 'User', // Fallback name
                   roles: ['buyer'],
                   is_banned: false
               });

               if (!insertError) {
                   user = await fetchUserProfile(data.user.id);
               } else {
                   console.error("Failed to create fallback profile", insertError);
                   return { success: false, error: "Account data corrupted. Please contact support." };
               }
          }

          fetchData();

          let role: Role = 'buyer';
          if (user) {
              if (user.roles.includes('admin')) role = 'admin';
              else if (user.roles.includes('vendor')) role = 'vendor';
              else if (user.roles.includes('deliveryPerson')) role = 'deliveryPerson';
          }
          return { success: true, role }; 
      }
      return { success: false };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role) => {
      // 1. Authenticate with Supabase
      const { data, error } = await supabase.auth.signUp({ 
          email, 
          password, 
          options: { data: { full_name: fullName, roles: [role] } } 
      });

      if (error) return { success: false, error: error.message };

      if (data.user) {
           // 2. Create Profile Record - Use UPSERT to prevent duplicate key errors
           const { error: profileError } = await supabase.from('profiles').upsert({ 
               id: data.user.id, 
               email, 
               name: fullName, 
               roles: [role],
               is_banned: false 
           });

           if (profileError) {
               console.error("Profile upsert failed:", profileError);
               // We continue because login might auto-heal
           }

           // 3. Optimized Login Flow
           if (data.session) {
               await fetchUserProfile(data.user.id);
               fetchData(); 
               return { success: true };
           }

           return await login(email, password);
      }
      return { success: false };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  const resetPassword = async (email: string) => { 
      const { error } = await supabase.auth.resetPasswordForEmail(email, { redirectTo: window.location.origin + '/#/update-password' });
      return { success: !error, error: error?.message }; 
  };

  const updatePassword = async (pass: string) => { 
      const { error } = await supabase.auth.updateUser({ password: pass });
      return { success: !error, error: error?.message }; 
  };

  const switchRole = (role: Role) => { if(currentUser?.roles.includes(role)) setCurrentRole(role); };

  // Utils
  const showToast = (message: string, type: 'success'|'error'|'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const requestNotificationPermission = async () => (await Notification.requestPermission()) === 'granted';

  // --- STORAGE UPLOAD HELPER ---
  const uploadFile = async (file: File, folder: string): Promise<string | null> => {
      try {
          const fileExt = file.name.split('.').pop();
          const fileName = `${Math.random().toString(36).substring(2, 15)}_${Date.now()}.${fileExt}`;
          const filePath = `${folder}/${fileName}`;

          const { error: uploadError } = await supabase.storage
              .from('lynqed-assets')
              .upload(filePath, file);

          if (uploadError) {
              console.error('Upload error:', uploadError);
              showToast(`Upload failed: ${uploadError.message}`, 'error');
              return null;
          }

          const { data } = supabase.storage.from('lynqed-assets').getPublicUrl(filePath);
          return data.publicUrl;
      } catch (error: any) {
          console.error('Storage error:', error);
          showToast('Image upload failed', 'error');
          return null;
      }
  };

  // Specific Actions
  const registerVendor = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };

      try {
          const { data: existing } = await supabase.from('vendors').select('id').eq('user_id', currentUser.id).maybeSingle();
          let error;
          if (existing) {
               const { error: upError } = await supabase.from('vendors').update({
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl
               }).eq('user_id', currentUser.id);
               error = upError;
          } else {
               const { error: inError } = await supabase.from('vendors').insert({ 
                   vendor_id: `v-${Date.now()}`, 
                   user_id: currentUser.id, 
                   store_name: data.storeName,
                   store_description: data.storeDescription,
                   location: data.location,
                   contact_phone: data.contactPhone,
                   store_avatar_url: data.storeAvatarUrl,
                   is_approved: false, 
                   rating: 5.0 
               });
               error = inError;
          }
          if (error) {
              showToast(`Registration failed: ${error.message || 'Database error'}`, "error");
              return { success: false };
          } 
          showToast("Store profile saved successfully", "success"); 
          await fetchData();
          return { success: true };
      } catch (e: any) {
          showToast(`Unexpected error: ${e.message || e}`, "error");
          return { success: false };
      }
  };

  const registerDeliveryPerson = async (data: any): Promise<{ success: boolean }> => {
      if(!currentUser) return { success: false };
      const { error } = await supabase.from('delivery_persons').insert({ 
          user_id: currentUser.id, 
          full_name: data.fullName,
          vehicle_type: data.vehicleType,
          status: 'pending' 
      });
      if (error) {
          showToast(`Application failed: ${error.message}`, "error");
          return { success: false };
      }
      showToast("Rider application submitted", "success"); 
      fetchData();
      return { success: true };
  };

  const addProduct = async (prod: any) => {
      if(!currentUser) { showToast("You must be logged in.", "error"); return false; }
      let v = vendors.find(v => v.userId === currentUser.id);
      if (!v) {
          try {
             const { data } = await supabase.from('vendors').select('*').eq('user_id', currentUser.id).maybeSingle();
             if(data) {
                 v = { ...data, vendorId: data.vendor_id, userId: data.user_id, storeName: data.store_name || 'My Store', storeDescription: '', location: '', isApproved: data.is_approved, rating: 5 };
             }
          } catch(e) {}
      }
      if(!v) { showToast("Vendor profile not found. Please set up your store.", "error"); return false; }

      const { customCategory, vendorId, ...dbProduct } = prod;
      const productPayload = {
          vendor_id: v.vendorId, 
          title: dbProduct.title,
          description: dbProduct.description,
          price: dbProduct.price,
          currency: 'GHS',
          category: dbProduct.category,
          images: dbProduct.images,
          stock: dbProduct.stock,
          status: 'pending',
          location: dbProduct.location,
          contact_phone: dbProduct.contactPhone
      };
      const { error } = await supabase.from('products').insert(productPayload);
      if (error) { showToast(`Failed to add product: ${error.message}`, "error"); return false; }
      showToast("Product submitted for approval", "success"); 
      fetchData(); 
      return true;
  };

  const updateProduct = async (id: string, data: any) => {
      const { customCategory, vendorId, contactPhone, ...rest } = data;
      const updatePayload = { ...rest, contact_phone: contactPhone };
      const { error } = await supabase.from('products').update(updatePayload).eq('id', id);
      if (error) { showToast("Update failed", "error"); } 
      else { showToast("Product updated", "success"); fetchData(); }
  };

  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };
  const updateCartQuantity = (pid: string, qty: number) => {
      if(qty <= 0) removeFromCart(pid);
      else setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };
  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);
  const toggleFavorite = (pid: string) => {
      const isFav = favorites.includes(pid);
      if (isFav) { setFavorites(prev => prev.filter(i => i !== pid)); showToast("Removed from Wishlist", "info"); } 
      else { setFavorites(prev => [...prev, pid]); showToast("Added to Wishlist ❤️", "success"); }
  };

  const placeOrder = async (option: 'delivery'|'pickup', fee = 0) => {
      if (!currentUser) return;
      const byVendor: any = {};
      cart.forEach(i => { if(!byVendor[i.product.vendorId]) byVendor[i.product.vendorId]=[]; byVendor[i.product.vendorId].push(i); });
      try {
          for(const vid in byVendor) {
              const items = byVendor[vid];
              const subtotal = items.reduce((s:number, i:any) => s + i.product.price * i.quantity, 0);
              const { error } = await supabase.from('orders').insert({ 
                  buyer_id: currentUser.id, 
                  vendor_id: vid, 
                  items, 
                  total: subtotal+fee, 
                  delivery_fee: fee, 
                  status: 'placed', 
                  delivery_option: option 
              });
              if (error) throw error;
          }
          showToast("Order Placed!", "success"); clearCart(); fetchData();
      } catch (e: any) { showToast(`Order failed: ${e.message}`, "error"); }
  };

  const updateOrderStatus = async (oid: string, status: string) => { await supabase.from('orders').update({status}).eq('id', oid); fetchData(); };
  const assignDelivery = async (oid: string) => { if(currentUser) await supabase.from('orders').update({ delivery_person_id: currentUser.id, status: 'assigned' }).eq('id', oid); fetchData(); };

  const banUser = async (uid: string, s: boolean) => { 
      try {
          const { data, error } = await supabase.from('profiles').update({ is_banned: s }).eq('id', uid).select();
          if (error) throw error;
          if (!data || data.length === 0) throw new Error("Permission denied or user not found.");
          showToast(s ? "User Banned" : "User Unbanned", "success"); fetchData(); 
      } catch (e: any) { showToast("Action failed: " + e.message, "error"); }
  };
  const deleteUser = async (uid: string) => { 
      try {
          const { data, error } = await supabase.from('profiles').delete().eq('id', uid).select();
          if (error) throw error;
          if (!data || data.length === 0) throw new Error("Permission denied.");
          showToast("User deleted", "success"); fetchData(); 
      } catch (e: any) { showToast("Delete failed: " + e.message, "error"); }
  };
  const approveVendor = async (vid: string, s: boolean) => { 
      showToast(s ? "Approving vendor..." : "Suspending vendor...", "info");
      try {
          const { data, error } = await supabase.from('vendors').update({ is_approved: s }).eq('vendor_id', vid).select();
          if (error) throw error;
          if (!data || data.length === 0) throw new Error("Permission denied.");
          await fetchData(); showToast(s ? "Vendor Approved" : "Vendor Suspended", "success");
      } catch (err: any) { showToast(`Failed: ${err.message}`, "error"); }
  };
  const approveDeliveryPerson = async (id: string, uid: string, status: string) => { 
      try {
          const { data, error } = await supabase.from('delivery_persons').update({status}).eq('id', id).select();
          if (error) throw error;
          if (!data || data.length === 0) throw new Error("Permission denied.");
          if(status === 'approved') {
               const { data: userData } = await supabase.from('profiles').select('roles').eq('id', uid).single();
               if(userData) {
                   const newRoles = [...(userData.roles || []), 'deliveryPerson'];
                   const uniqueRoles = Array.from(new Set(newRoles));
                   await supabase.from('profiles').update({roles: uniqueRoles}).eq('id', uid);
               }
          }
          showToast("Rider updated", "success"); fetchData(); 
      } catch (e: any) { showToast("Action failed: " + e.message, "error"); }
  };
  const updateProductStatus = async (id: string, status: string) => { 
      try {
        const { data, error } = await supabase.from('products').update({status}).eq('id', id).select(); 
        if (error) throw error;
        if (!data || data.length === 0) throw new Error("Permission denied.");
        showToast(`Product ${status}`, "success"); fetchData(); 
      } catch(e: any) { showToast("Update failed: " + e.message, "error"); }
  };
  const deleteProduct = async (id: string) => { 
      try {
        const { data, error } = await supabase.from('products').delete().eq('id', id).select(); 
        if (error) throw error;
        if (!data || data.length === 0) throw new Error("Permission denied.");
        showToast("Product deleted", "success"); fetchData(); 
      } catch(e: any) { showToast("Delete failed: " + e.message, "error"); }
  };

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, deliveryPersons, users, isLoading, isDataLoading, cart, favorites, toast,
        login, signup, logout, resetPassword, updatePassword, switchRole,
        uploadFile, registerVendor, registerDeliveryPerson, refreshData: fetchData,
        addProduct, updateProduct, updateProductStatus, deleteProduct,
        addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, assignDelivery, toggleFavorite,
        banUser, deleteUser, approveVendor, approveDeliveryPerson,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { useState } from 'react';
import { useApp } from '../context';
import { Button, Input } from '../components/UI';
import { useNavigate, Link, useLocation } from 'react-router-dom';
import { Role } from '../types';

export const Login: React.FC = () => {
    const { login } = useApp();
    const navigate = useNavigate();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    const handleLogin = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setIsLoading(true);

        try {
            const result = await login(email, password);

            if (result.success) {
                if (result.role === 'admin') navigate('/admin/dashboard');
                else if (result.role === 'vendor') navigate('/vendor/dashboard');
                else if (result.role === 'deliveryPerson') navigate('/delivery/dashboard');
                else navigate('/buyer/dashboard');
            } else {
                setError(result.error || 'Login failed');
            }
        } catch (err) {
            setError('An unexpected error occurred during login.');
            console.error(err);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-white relative overflow-hidden">
            <div className="absolute top-[-10%] right-[-10%] w-64 h-64 bg-primary/10 rounded-full blur-3xl"></div>
            <div className="absolute bottom-[-10%] left-[-10%] w-80 h-80 bg-secondary/10 rounded-full blur-3xl"></div>

            <div className="flex-1 flex flex-col justify-center px-8 py-12 relative z-10 max-w-md mx-auto w-full animate-fade-in">
                <div className="mb-8 text-center">
                    <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-gradient-to-tr from-primary to-secondary text-white text-2xl shadow-glow mb-4">
                         <i className="fa-solid fa-bolt"></i>
                    </div>
                    <h1 className="text-3xl font-display font-extrabold text-gray-900">Welcome Back</h1>
                    <p className="text-gray-500 mt-2">Sign in to continue to LYNQED</p>
                </div>

                {error && (
                    <div className="bg-red-50 border border-red-100 text-red-600 text-sm p-3 rounded-xl mb-4 flex items-center">
                        <i className="fa-solid fa-circle-exclamation mr-2"></i>
                        {error}
                    </div>
                )}

                <form onSubmit={handleLogin} className="space-y-6">
                    <Input 
                        label="Email Address" 
                        icon="envelope" 
                        type="email"
                        placeholder="you@university.edu" 
                        value={email} 
                        onChange={e => setEmail(e.target.value)} 
                        required
                    />

                    <div>
                        <Input 
                            label="Password" 
                            icon="lock" 
                            type="password"
                            placeholder="••••••••" 
                            value={password}
                            onChange={e => setPassword(e.target.value)}
                            required
                        />
                        <div className="flex justify-end -mt-3 mb-2">
                            <Link 
                                to="/forgot-password"
                                className="text-xs font-bold text-primary hover:text-primaryDark transition-colors"
                            >
                                Forgot Password?
                            </Link>
                        </div>
                    </div>

                    <Button 
                        fullWidth 
                        size="lg" 
                        type="submit"
                        disabled={isLoading}
                        className="shadow-xl shadow-primary/30"
                    >
                        {isLoading ? 'Signing in...' : 'Sign In'}
                    </Button>
                </form>

                <div className="mt-8 text-center text-sm text-gray-500">
                    Don't have an account? <Link to="/register" className="font-bold text-primary hover:text-primaryDark transition-colors">Create Account</Link>
                </div>
            </div>
        </div>
    );
};

export const ForgotPassword: React.FC = () => {
    const { resetPassword, showToast } = useApp();
    const navigate = useNavigate();
    const [email, setEmail] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    const handleReset = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setIsLoading(true);

        try {
            const result = await resetPassword(email);
            if (result.success) {
                showToast("Reset link sent! Check your email.", "success");
                navigate('/login');
            } else {
                setError(result.error || 'Failed to send reset email.');
            }
        } catch (err) {
            setError('An error occurred.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-white relative overflow-hidden">
            <div className="absolute top-[-10%] left-[-10%] w-64 h-64 bg-primary/10 rounded-full blur-3xl"></div>
            <div className="flex-1 flex flex-col justify-center px-8 py-12 relative z-10 max-w-md mx-auto w-full animate-slide-up">
                <div className="mb-6 text-center">
                    <h1 className="text-2xl font-display font-extrabold text-gray-900">Reset Password</h1>
                    <p className="text-gray-500 mt-2 text-sm">Enter your email to receive reset instructions</p>
                </div>

                {error && (
                    <div className="bg-red-50 border border-red-100 text-red-600 text-sm p-3 rounded-xl mb-4">
                        {error}
                    </div>
                )}

                <form onSubmit={handleReset} className="space-y-6">
                    <Input 
                        label="Email Address" 
                        icon="envelope" 
                        type="email"
                        placeholder="you@university.edu" 
                        value={email} 
                        onChange={e => setEmail(e.target.value)} 
                        required
                    />
                    <Button 
                        fullWidth 
                        size="lg" 
                        type="submit"
                        disabled={isLoading}
                    >
                        {isLoading ? 'Sending...' : 'Send Reset Link'}
                    </Button>
                </form>

                <div className="mt-6 text-center">
                    <Link to="/login" className="text-sm font-bold text-gray-500 hover:text-gray-900">Back to Login</Link>
                </div>
            </div>
        </div>
    );
};

export const UpdatePassword: React.FC = () => {
    const { updatePassword, showToast } = useApp();
    const navigate = useNavigate();
    const [password, setPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    const handleUpdate = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setIsLoading(true);

        try {
            const result = await updatePassword(password);
            if (result.success) {
                showToast("Password updated successfully!", "success");
                navigate('/login');
            } else {
                setError(result.error || 'Failed to update password.');
            }
        } catch (err) {
            setError('Update failed.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex flex-col bg-white relative overflow-hidden">
            <div className="absolute bottom-[-10%] right-[-10%] w-64 h-64 bg-secondary/10 rounded-full blur-3xl"></div>
            <div className="flex-1 flex flex-col justify-center px-8 py-12 relative z-10 max-w-md mx-auto w-full animate-slide-up">
                <div className="mb-6 text-center">
                    <h1 className="text-2xl font-display font-extrabold text-gray-900">Set New Password</h1>
                    <p className="text-gray-500 mt-2 text-sm">Create a strong, secure password</p>
                </div>

                {error && (
                    <div className="bg-red-50 border border-red-100 text-red-600 text-sm p-3 rounded-xl mb-4">
                        {error}
                    </div>
                )}

                <form onSubmit={handleUpdate} className="space-y-6">
                    <Input 
                        label="New Password" 
                        icon="lock" 
                        type="password"
                        placeholder="New secure password" 
                        value={password}
                        onChange={e => setPassword(e.target.value)} 
                        required
                        minLength={6}
                    />
                    <Button 
                        fullWidth 
                        size="lg" 
                        type="submit"
                        disabled={isLoading}
                    >
                        {isLoading ? 'Updating...' : 'Update Password'}
                    </Button>
                </form>
            </div>
        </div>
    );
};

